const express = require('express');
const path = require('path');
const fs = require('fs');
const crypto = require('crypto');
const cors = require('cors');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
require('dotenv').config();
// 참고: 인증은 전부 Supabase Auth(supabase.auth.getUser)로 처리하므로
// jsonwebtoken을 이용한 자체 JWT 발급/검증 로직은 사용하지 않습니다.

const { createClient } = require('@supabase/supabase-js');
const cron = require('node-cron');

// 대표자 전용 원가/2FA 인프라용 라이브러리
// - bcryptjs: 백업코드/OTP 코드 해시 (네이티브 컴파일이 필요한 bcrypt 대신 순수 JS 구현을 사용 - Windows 서버에
//   빌드 도구 없이도 설치/실행되도록 하기 위함. API는 bcrypt와 동일)
// - otplib: TOTP(구글 OTP 앱 호환) 생성/검증
// - qrcode: TOTP 등록용 QR코드 이미지(data URL) 생성
const bcrypt = require('bcryptjs');
const { authenticator } = require('otplib');
const QRCode = require('qrcode');


// ============================================
// Supabase 초기화
// ============================================
const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL;
const supabaseServiceKey = process.env.SUPABASE_SERVICE_ROLE_KEY;
const supabaseAnonKey = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY;

// 관리자 권한 클라이언트 (SERVICE_ROLE_KEY)
const supabase = createClient(supabaseUrl, supabaseServiceKey);

// 공개 클라이언트 (ANON_KEY) - RLS 정책이 적용됨
const supabasePublic = createClient(supabaseUrl, supabaseAnonKey);

const app = express();
const PORT = process.env.PORT || 3000;

// 🔒 JWT_SECRET 미설정 시 안전장치: 예전에는 고정 문자열('withplus-fallback-secret')로 fail-open 됐는데,
// 이 문자열은 소스코드에 그대로 공개되어 있어 JWT_SECRET을 깜빡하고 설정하지 않으면 누구나 같은 값으로
// 서명을 위조할 수 있는 상태가 된다. 대신 프로세스 시작 시 1회 랜덤 시크릿을 생성해두고, 환경변수가
// 없을 때만 이 런타임 전용 값을 폴백으로 쓰도록 바꿔 "공개된 고정 문자열"이 되는 것만은 막는다
// (재시작마다 값이 바뀌므로 재시작 전에 발급된 서명은 재시작 후 무효화된다 - 그래도 값을 아무도 예측할 수
// 없는 것이 하드코딩된 고정값보다 훨씬 안전하다). 운영 환경에서는 반드시 JWT_SECRET을 설정해야 한다.
if (!process.env.JWT_SECRET) {
  console.error('[SECURITY WARNING] JWT_SECRET 환경변수가 설정되지 않았습니다. 프로세스 시작 시 생성한 런타임 전용 임시 시크릿을 대신 사용합니다. 재시작 시 이전에 발급된 서명은 모두 무효화됩니다. 반드시 .env에 JWT_SECRET을 설정해주세요.');
}
const RUNTIME_FALLBACK_SECRET = crypto.randomBytes(32).toString('hex');

// ============================================
// 📺 라이브커머스 테이블 스위치 (WITH+ / LIVE+ 데이터 분리)
// ============================================
// WITH+와 LIVE+는 같은 Supabase DB를 쓰지만 라이브 데이터(채널·세션·채팅·퀴즈·경매·쿠폰함·OmniCast 연결 등)는
// 사이트별로 완전히 분리한다. LIVE+는 *_live 테이블, WITH+는 *_with 테이블을 쓴다(2026-10-22 마이그레이션
// docs/migrations/2026-10-22_live_commerce_with.sql). 같은 코드가 어느 사이트에서든 돌 수 있도록 라이브 테이블 이름은
// 반드시 liveTable('<기본이름>')으로만 만든다 - '_live'/'_with'를 코드에 직접 박아 넣지 않는다.
//  - 상품·주문·회원·쿠폰(products_with·orders_with·profiles·coupons…)처럼 원래 두 사이트가 함께 쓰는 테이블은 그대로 공유.
//  - LIVE+에서 접미사 없이 쓰던 전역 테이블(omnicast_*)과 LIVE+ 크리에이터 테이블(creators_with 등, 이름이 이미
//    _with라 WITH+는 live_creators_with 등을 쓴다)은 아래 예외표로 매핑한다.
//  - orders_with(공유)의 channel_id/live_session_id/creator_id는 LIVE+ 테이블을 가리키는 FK라, WITH+ 라이브 주문은
//    live_channel_id_with/live_session_id_with/live_creator_id_with 컬럼(LIVE_ORDER_COL)에 기록한다.
// 사이트 판별은 기존 UPLOAD_PLATFORM(사진 업로드 폴더 구분)과 같은 환경변수를 쓴다(기본값 withplus).
const LIVE_SITE = (process.env.UPLOAD_PLATFORM || 'withplus') === 'liveplus' ? 'liveplus' : 'withplus';
const IS_LIVEPLUS_SITE = LIVE_SITE === 'liveplus';
const LIVE_SUFFIX = IS_LIVEPLUS_SITE ? '_live' : '_with';
const LIVE_TABLE_LIVEPLUS_NAMES = {
  omnicast_platform_configs: 'omnicast_platform_configs',
  omnicast_pending_facebook_selections: 'omnicast_pending_facebook_selections',
  live_creators: 'creators_with',
  live_creator_referral_codes: 'creator_referral_codes_with',
  live_creator_settlements: 'creator_settlements_with'
};
function liveTable(base) {
  if (IS_LIVEPLUS_SITE && Object.prototype.hasOwnProperty.call(LIVE_TABLE_LIVEPLUS_NAMES, base)) return LIVE_TABLE_LIVEPLUS_NAMES[base];
  return base + LIVE_SUFFIX;
}
// 라이브 전용 RPC - LIVE+는 원래 이름(award_quiz_win 등), WITH+는 <이름>_with(*_with 테이블만 다룸).
// (reserve_channel_stock/release_channel_stock/adjust_stock_with는 공유 재고 RPC라 이 함수를 쓰지 않는다)
function liveRpc(name) { return IS_LIVEPLUS_SITE ? name : `${name}_with`; }
// 라이브 설정(platform_settings) 키 - LIVE+는 원래 키, WITH+는 <키>_with
function liveSettingKey(key) { return IS_LIVEPLUS_SITE ? key : `${key}_with`; }
// 공유 주문 테이블(orders_with)의 라이브 출처 컬럼
const LIVE_ORDER_COL = IS_LIVEPLUS_SITE
  ? { channel: 'channel_id', session: 'live_session_id', creator: 'creator_id' }
  : { channel: 'live_channel_id_with', session: 'live_session_id_with', creator: 'live_creator_id_with' };
const LIVE_SITE_LABEL = IS_LIVEPLUS_SITE ? 'LIVE+' : 'WITH+ 라이브';

// OmniCast(YouTube/Facebook OAuth access_token·refresh_token, 커스텀 RTMP stream_key) 저장용 암호화 키.
// OMNICAST_ENCRYPTION_KEY 환경변수(32바이트를 hex로 인코딩한 64자 문자열)를 우선 사용하고, 없으면
// JWT_SECRET 폴백(RUNTIME_FALLBACK_SECRET)과 동일한 패턴으로 프로세스가 시작될 때마다 새로 생성되는
// 임의의 32바이트 값으로 폴백한다.
// 트레이드오프 주의: 폴백을 쓰는 경우 서버가 재시작되면 키가 바뀌어, 그 이전에 이 키로 암호화 저장해둔
// access_token/refresh_token/stream_key를 더 이상 복호화할 수 없게 된다(YouTube/Facebook 재연결,
// 커스텀 RTMP 스트림키 재입력이 필요해짐) - 운영 환경에서는 반드시 OMNICAST_ENCRYPTION_KEY를 고정값으로 설정해야 한다.
let omnicastEncryptionKey;
if (process.env.OMNICAST_ENCRYPTION_KEY) {
  const keyBuf = Buffer.from(process.env.OMNICAST_ENCRYPTION_KEY, 'hex');
  if (keyBuf.length === 32) {
    omnicastEncryptionKey = keyBuf;
  } else {
    console.warn('⚠️  OMNICAST_ENCRYPTION_KEY는 32바이트(hex 64자)여야 합니다. 형식이 올바르지 않아 런타임 임의 키로 폴백합니다.');
    omnicastEncryptionKey = crypto.randomBytes(32);
  }
} else {
  console.warn('⚠️  OMNICAST_ENCRYPTION_KEY 환경변수가 설정되지 않아 OmniCast 토큰/스트림키를 런타임 임의 키로 암호화합니다. 서버가 재시작되면 기존에 암호화 저장된 값을 복호화할 수 없게 되니(YouTube/Facebook 재연결, RTMP 키 재입력 필요), 운영 환경에서는 반드시 OMNICAST_ENCRYPTION_KEY를 고정값으로 설정하세요.');
  omnicastEncryptionKey = crypto.randomBytes(32);
}

// AES-256-GCM으로 OmniCast 시크릿(OAuth access_token/refresh_token, RTMP stream_key)을 암호화한다.
// 반환값 형식: "enc:v1:<iv-hex>:<authTag-hex>:<ciphertext-hex>" - 접두사(enc:v1:)로 기존에 평문으로
// 저장돼 있던(이번 수정 이전의, 마이그레이션 전) 값과 구분한다. null/빈 문자열은 그대로 null로 저장한다.
function encryptSecret(text) {
  if (text === null || text === undefined || text === '') return null;
  const iv = crypto.randomBytes(12); // GCM 권장 IV 길이(12바이트)
  const cipher = crypto.createCipheriv('aes-256-gcm', omnicastEncryptionKey, iv);
  const encrypted = Buffer.concat([cipher.update(String(text), 'utf8'), cipher.final()]);
  const authTag = cipher.getAuthTag();
  return `enc:v1:${iv.toString('hex')}:${authTag.toString('hex')}:${encrypted.toString('hex')}`;
}

// encryptSecret으로 암호화된 값을 복호화한다. "enc:v1:" 접두사가 없으면(이번 수정 이전에 평문으로 저장된
// 기존 값 - 별도 마이그레이션 전까지는 평문으로 남아있다) 그대로 돌려준다(하위호환). 복호화 자체가
// 실패하면(암호화 키가 그 사이 바뀐 경우 등) null을 돌려주고 에러만 로그로 남긴다.
function decryptSecret(stored) {
  if (stored === null || stored === undefined || stored === '') return stored;
  if (typeof stored !== 'string' || !stored.startsWith('enc:v1:')) return stored; // 평문(마이그레이션 전) 하위호환
  try {
    const [, , ivHex, authTagHex, dataHex] = stored.split(':');
    const decipher = crypto.createDecipheriv('aes-256-gcm', omnicastEncryptionKey, Buffer.from(ivHex, 'hex'));
    decipher.setAuthTag(Buffer.from(authTagHex, 'hex'));
    const decrypted = Buffer.concat([decipher.update(Buffer.from(dataHex, 'hex')), decipher.final()]);
    return decrypted.toString('utf8');
  } catch (err) {
    console.error('OmniCast 시크릿 복호화 실패 (암호화 키가 바뀌었을 수 있음):', err.message);
    return null;
  }
}

// ============================================
// 미들웨어
// ============================================
// 🔒 CSP(Content-Security-Policy): 전면 비활성화 대신 최소한의 CSP를 적용한다. 이 코드베이스는 여러
// 화면에서 인라인 <script>/<style>을 광범위하게 사용하므로(카페24에서 이전한 레거시 페이지 다수 포함),
// script-src/style-src에서 'unsafe-inline'(및 동적 스크립트 생성을 쓰는 일부 화면을 위해 'unsafe-eval')을
// 완전히 제거하면 사이트 여러 곳이 그대로 깨진다. 그래서 object-src/base-uri/frame-ancestors 등 부작용
// 없이 방어력을 높일 수 있는 지시문은 강하게 잠그고, script-src/style-src는 'unsafe-inline'을 유지하는
// 선에서 최소 방어(외부 origin 제한 등)만 추가하는 절충안을 택했다.
// TODO: 인라인 스크립트/스타일을 nonce 기반으로 전환하면 'unsafe-inline'을 제거하고 더 강하게 조일 수 있다.
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      ...helmet.contentSecurityPolicy.getDefaultDirectives(),
      "script-src": ["'self'", "'unsafe-inline'", "'unsafe-eval'", "https:"],
      "style-src": ["'self'", "'unsafe-inline'", "https:"],
      "img-src": ["'self'", "data:", "https:", "blob:"],
      "connect-src": ["'self'", "https:", "wss:"],
      // 📺 라이브(WITH+ 라이브커머스): 유튜브/페이스북 임베드 재생, Cloudflare Stream HLS(blob: MSE), hls.js 워커(blob:)
      "frame-src": ["'self'", "https://www.youtube.com", "https://www.youtube-nocookie.com", "https://www.facebook.com", "https://web.facebook.com"],
      "media-src": ["'self'", "https:", "blob:", "data:"],
      "worker-src": ["'self'", "blob:"],
      "object-src": ["'none'"],
      "base-uri": ["'self'"],
      "frame-ancestors": ["'self'"],
    },
  },
}));
app.use(cors());
app.use(express.json());
app.use(express.urlencoded({ extended: true }));

// ============================================
// Rate Limiting - 격차분석에서 짚었던 "API 남용 방어 전무" 항목 해결.
// 로그인 자체는 클라이언트가 Supabase Auth를 직접 호출하므로(이 서버를 거치지 않음) 여기서 막을 수 없지만,
// 이 서버가 직접 처리하는 API 전반(특히 쿠폰 코드처럼 무작위 대입 공격이 가능한 것들)은 방어가 전혀 없었다.
// 프록시(ALB/nginx) 뒤에 놓일 가능성을 고려해 X-Forwarded-For 첫 번째 IP를 신뢰한다(현재는 EC2에 직접
// 노출되어 있지만, 도메인 연결 시 CloudFront/ALB를 앞에 두는 것이 일반적인 구성이라 미리 대응해둔다).
app.set('trust proxy', 1);

// 전체 API 공통 - 넉넉하지만 스크래핑/전수조사성 남용은 막는 기본 방어선
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15분
  max: 600,
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too Many Requests', message: '요청이 너무 많습니다. 잠시 후 다시 시도해주세요.', timestamp: new Date().toISOString() }
});
app.use('/api/', apiLimiter);

// 쿠폰 코드(시리얼 쿠폰/일반 쿠폰) 검증·등록 - 코드를 무작위로 대입해보는 공격이 가능한 엔드포인트라 훨씬 엄격하게 제한
const couponLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 20,
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too Many Requests', message: '쿠폰 코드 시도 횟수가 너무 많습니다. 15분 후 다시 시도해주세요.', timestamp: new Date().toISOString() }
});
app.use('/api/serial-coupons/redeem', couponLimiter);
app.use('/api/coupons/validate', couponLimiter);

// 📺 라이브 팬 활동 점수 API - view/share처럼 서버가 실제 발생 여부를 검증할 수 없는 가벼운 활동은, 클라이언트가
// 짧은 시간에 반복 호출해 점수를 긁어가는 남용을 막기 위해 별도로 더 엄격하게 제한한다.
const fanActivityLimiter = rateLimit({
  windowMs: 5 * 60 * 1000,
  max: 30,
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too Many Requests', message: '활동 기록 요청이 너무 많습니다. 잠시 후 다시 시도해주세요.', timestamp: new Date().toISOString() }
});

// 📺 라이브 채팅 도배 방지 - 같은 사용자가 보낸 두 요청이 동시에 도착해도(TOCTOU 레이스) 사용자 단위로
// 짧은 시간창(2초)에 1회만 허용한다(라우트 핸들러 진입 전에 걸러낸다). authenticate 뒤에 붙으므로 req.user가 있다.
const liveChatLimiter = rateLimit({
  windowMs: 2 * 1000,
  max: 1,
  standardHeaders: true,
  legacyHeaders: false,
  keyGenerator: (req) => (req.user && req.user.id) || rateLimit.ipKeyGenerator(req.ip),
  message: { error: 'Too Many Requests', message: '메시지를 너무 빠르게 보내고 있어요. 잠시 후 다시 시도해주세요', timestamp: new Date().toISOString() }
});

// ============================================
// 설치형 앱(PWA) 표준 v1 — 매니페스트·아이콘·서비스워커·오프라인 화면은 로그인 없이 열린다(인증 미들웨어보다 앞).
// sw.js 는 no-cache 로 내려 배포 즉시 새 워커가 반영되게 한다. (PWA_APP_STANDARD.md)
// ============================================
const PWA_PUBLIC_DIR = path.join(__dirname, 'public');
const PWA_ICON_FILES = { '192': 'icon-192.png', '512': 'icon-512.png', maskable: 'icon-512-maskable.png', apple: 'apple-touch-icon.png' };
app.get(['/manifest.webmanifest', '/manifest.json'], (req, res) => {
  res.type('application/manifest+json');
  res.sendFile(path.join(PWA_PUBLIC_DIR, 'manifest.json'), { cacheControl: false, headers: { 'Cache-Control': 'public, max-age=3600' } });
});
app.get('/sw.js', (req, res) => {
  res.type('application/javascript');
  res.sendFile(path.join(PWA_PUBLIC_DIR, 'sw.js'), {
    cacheControl: false,
    headers: { 'Cache-Control': 'no-cache, no-store, must-revalidate', 'Service-Worker-Allowed': '/' }
  });
});
app.get('/offline.html', (req, res) => {
  res.sendFile(path.join(PWA_PUBLIC_DIR, 'offline.html'), { cacheControl: false, headers: { 'Cache-Control': 'no-cache' } });
});
app.get('/pwa/icon/:size', (req, res, next) => {
  const file = PWA_ICON_FILES[req.params.size];
  if (!file) return next();
  res.sendFile(path.join(PWA_PUBLIC_DIR, 'images', 'icons', file), { maxAge: '7d' });
});
// 📱 Play 스토어 앱(TWA) 연결 확인 파일 — 구글이 "이 앱이 이 사이트의 공식 앱"인지 확인할 때 읽는다.
// 패키지명·서명키 지문(SHA-256)은 형님이 앱을 만든 뒤 환경변수로 넣는다(docs/APP_STORE_GUIDE.md).
//   TWA_PACKAGE_NAME=kr.withplus.app
//   TWA_SHA256_FINGERPRINTS=AA:BB:...(여러 개면 쉼표로 구분 — 업로드 키 + Play 앱 서명 키)
// 값이 없으면 빈 배열([])을 내려 아무 앱도 연결되지 않게 한다(가짜 키를 지어내지 않음).
app.get('/.well-known/assetlinks.json', (req, res) => {
  const pkg = String(process.env.TWA_PACKAGE_NAME || '').trim();
  const fps = String(process.env.TWA_SHA256_FINGERPRINTS || '')
    .split(',')
    .map(s => s.trim().toUpperCase())
    .filter(s => /^([0-9A-F]{2}:){31}[0-9A-F]{2}$/.test(s));
  const body = (pkg && /^[a-zA-Z][\w]*(\.[a-zA-Z][\w]*)+$/.test(pkg) && fps.length > 0)
    ? [{ relation: ['delegate_permission/common.handle_all_urls'], target: { namespace: 'android_app', package_name: pkg, sha256_cert_fingerprints: fps } }]
    : [];
  res.set('Cache-Control', 'public, max-age=300');
  res.type('application/json').send(JSON.stringify(body));
});

// 정적 파일 서빙 (홈페이지: public/index.html)
app.use(express.static(path.join(__dirname, 'public')));

// 인증 미들웨어
// 회원가입(join.html)은 client.auth.signUp()만 호출하는 순수 Supabase Auth 방식이라, auth.users에는
// 계정이 생기지만 이 코드베이스 어디에도 profiles 행을 만들어주는 곳이 없었다(테스트 스크립트만
// admin.auth.admin.createUser 직후 별도로 profiles를 upsert해왔기 때문에 지금까지 드러나지 않았던
// 실제 버그). profiles가 없으면 주문/리뷰/마일리지 등 거의 모든 기능이 조회 실패로 조용히 깨지므로,
// 인증 미들웨어에서 매 요청마다 정직하게 확인해 없으면 만들어준다. 이미 확인된 사용자는 메모리에
// 캐시해 매 요청마다 DB를 다시 조회하지 않도록 한다(서버 재시작 전까지 유효 - shippingPolicyCache 등
// 기존의 인메모리 캐시 패턴과 동일).
// knownProfileUserIds는 "존재 + 탈퇴하지 않음(활성)"이 확인된 사용자만 캐시한다. 탈퇴 처리(회원탈퇴 API)
// 시점에 이 캐시에서 즉시 제거되므로, 캐시에 없는 사용자는 항상 DB에서 다시 확인한다.
const knownProfileUserIds = new Set();
async function ensureProfileExists(user) {
  if (knownProfileUserIds.has(user.id)) return { active: true };
  try {
    const { data: existing } = await supabase.from('profiles').select('id, is_active').eq('id', user.id).maybeSingle();
    if (existing) {
      // is_active가 명시적으로 false면 탈퇴한 계정 - is_active 컬럼 자체를 아직 안 쓰는 기존 회원은
      // null/undefined이므로 활성으로 취급한다(회원탈퇴 API가 탈퇴 시에만 명시적으로 false를 넣음).
      if (existing.is_active === false) return { active: false };
      knownProfileUserIds.add(user.id);
      return { active: true };
    }
    const meta = user.user_metadata || {};
    const { error: insertErr } = await supabase.from('profiles').upsert([{
      id: user.id,
      email: user.email,
      full_name: meta.full_name || meta.name || null, // 소셜 로그인(구글/카카오) 제공자별로 메타데이터 키가 다를 수 있어 둘 다 확인
      role: 'member',
      member_type: 'general'
    }], { onConflict: 'id', ignoreDuplicates: true });
    if (insertErr) throw insertErr;
    knownProfileUserIds.add(user.id);
    return { active: true };
  } catch (err) {
    console.error('Error ensuring profile exists for user', user.id, ':', err.message);
    // 조회 자체가 실패한 경우(일시적 DB 오류 등)까지 차단하면 서비스 전체가 막히므로, 기존 동작과 동일하게 통과시킨다.
    return { active: true };
  }
}

// JWT의 페이로드(가운데 부분)만 디코딩해 AAL(Authenticator Assurance Level) 클레임을 읽어온다.
// 서명 검증은 이미 supabase.auth.getUser(token)이 Supabase 서버에 물어봐서 대신해주므로, 여기서는
// 이미 신뢰할 수 있다고 확인된 토큰의 클레임만 꺼내 쓴다(추가 서명 검증이 필요 없음).
function decodeJwtAal(token) {
  try {
    const payload = JSON.parse(Buffer.from(token.split('.')[1], 'base64').toString('utf8'));
    return payload.aal || 'aal1';
  } catch (e) {
    return 'aal1';
  }
}

// amr(Authentication Methods Reference) 클레임 - "언제 어떤 방법으로 인증했는지"의 이력 배열
// ({method, timestamp} 형태)이다. 대표자 스텝업을 "내 계정 2FA"(Supabase Auth MFA)로 병합할 때
// "방금 TOTP로 aal2를 통과했는지"의 신선도를 검사하는 용도로만 쓴다(/api/admin/owner/stepup/via-account-mfa
// 참고). decodeJwtAal과 마찬가지로 서명 검증은 이미 끝난 토큰의 클레임만 꺼내 쓰는 것이라 안전하다.
function decodeJwtAmr(token) {
  try {
    const payload = JSON.parse(Buffer.from(token.split('.')[1], 'base64').toString('utf8'));
    return Array.isArray(payload.amr) ? payload.amr : [];
  } catch (e) {
    return [];
  }
}

const authenticate = async (req, res, next) => {
  try {
    const token = req.headers.authorization?.split(' ')[1];

    if (!token) {
      return res.status(401).json({
        error: 'Unauthorized',
        message: 'Authentication token required',
        timestamp: new Date().toISOString()
      });
    }

    // Supabase에서 토큰 검증
    const { data: { user }, error } = await supabase.auth.getUser(token);

    if (error || !user) {
      return res.status(401).json({
        error: 'Unauthorized',
        message: 'Invalid or expired token',
        timestamp: new Date().toISOString()
      });
    }

    req.user = user;
    req.authAal = decodeJwtAal(token);
    const profileStatus = await ensureProfileExists(user);
    if (!profileStatus.active) {
      return res.status(403).json({
        error: 'Forbidden',
        message: '탈퇴 처리된 계정입니다',
        timestamp: new Date().toISOString()
      });
    }
    next();
  } catch (err) {
    res.status(401).json({
      error: 'Unauthorized',
      message: err.message,
      timestamp: new Date().toISOString()
    });
  }
};

// authenticate와 달리 토큰이 없거나 유효하지 않아도 요청을 막지 않고 그냥 req.user 없이 통과시킨다.
// 비로그인 방문자의 행동(클릭/체류시간 등)도 기록하고 싶은 엔드포인트(예: /api/interactions)에서 사용 -
// 로그인 상태면 개인화 신호로 이어붙이고, 비로그인이면 익명으로만 기록한다.
const optionalAuth = async (req, res, next) => {
  try {
    const token = req.headers.authorization?.split(' ')[1];
    if (!token) return next();
    const { data: { user }, error } = await supabase.auth.getUser(token);
    if (!error && user) req.user = user;
  } catch (err) { /* 토큰 검증 실패해도 비로그인으로 취급하고 계속 진행 */ }
  next();
};

// ============================================
// 사용자 행동 이벤트 기록 (개인화 추천 알고리즘의 입력 신호)
// ============================================
// 상품상세 진입(view)/이탈(view_end + 체류시간)/장바구니 담기(cart_add)/삭제(cart_remove)를 기록한다.
// 로그인 여부와 무관하게 호출되므로 optionalAuth를 사용하고, 비로그인 방문자는 user_id 없이(익명으로) 저장한다.
// 프론트엔드의 트래킹 호출(특히 sendBeacon으로 보내는 view_end)이 실패해도 사용자 경험에 영향이 없어야 하므로
// 유효성 검증만 엄격히 하고 DB 오류는 관대하게(로그만 남기고 200) 처리한다.
const VALID_INTERACTION_EVENTS = ['view', 'view_end', 'cart_add', 'cart_remove', 'impression'];
// 목록에서 상품이 화면에 실제로 보인 시간(impression) 등을 페이지를 떠날 때 한 번에 묶어 보낸다(최대 60건)
app.post('/api/interactions/batch', optionalAuth, async (req, res) => {
  try {
    const events = Array.isArray(req.body && req.body.events) ? req.body.events.slice(0, 60) : [];
    const rows = events
      .filter(e => e && typeof e.product_id === 'string' && /^[0-9a-f-]{36}$/i.test(e.product_id) && VALID_INTERACTION_EVENTS.includes(e.event_type))
      .map(e => ({
        user_id: req.user ? req.user.id : null,
        product_id: e.product_id,
        category: e.category ? String(e.category).slice(0, 100) : null,
        event_type: e.event_type,
        dwell_ms: Number.isFinite(Number(e.dwell_ms)) && Number(e.dwell_ms) >= 0 ? Math.min(Math.round(Number(e.dwell_ms)), 600000) : null,
        session_id: e.session_id ? String(e.session_id).slice(0, 200) : null
      }));
    if (rows.length) {
      const { error } = await supabase.from('product_interactions_with').insert(rows);
      if (error) console.error('행동 이벤트 묶음 기록 실패:', error.message);
    }
    res.status(204).end();
  } catch (err) {
    res.status(204).end();
  }
});

app.post('/api/interactions', optionalAuth, async (req, res) => {
  try {
    const { product_id, event_type, dwell_ms, session_id, category } = req.body || {};
    if (!product_id || typeof product_id !== 'string') {
      return res.status(400).json({ error: 'Bad Request', message: 'product_id가 필요합니다', timestamp: new Date().toISOString() });
    }
    if (!VALID_INTERACTION_EVENTS.includes(event_type)) {
      return res.status(400).json({ error: 'Bad Request', message: `event_type은 ${VALID_INTERACTION_EVENTS.join('/')} 중 하나여야 합니다`, timestamp: new Date().toISOString() });
    }
    let dwellMs = null;
    if (dwell_ms !== undefined && dwell_ms !== null) {
      const n = Number(dwell_ms);
      if (Number.isFinite(n) && n >= 0) dwellMs = Math.round(n);
    }

    const { error } = await supabase.from('product_interactions_with').insert([{
      user_id: req.user ? req.user.id : null,
      product_id,
      category: category ? String(category).slice(0, 100) : null,
      event_type,
      dwell_ms: dwellMs,
      session_id: session_id ? String(session_id).slice(0, 200) : null
    }]);
    if (error) {
      // product_id가 삭제된 상품이거나 FK 위반 등 - 트래킹 실패가 사용자 경험을 막아서는 안 되므로 로그만 남긴다.
      console.error('행동 이벤트 기록 실패:', error.message);
      return res.status(204).end();
    }
    res.status(204).end();
  } catch (err) {
    console.error('Error recording interaction:', err);
    // 트래킹 엔드포인트는 실패해도 프론트를 막지 않는다.
    res.status(204).end();
  }
});

