// 🙏 GIVE+ 1단계: 종교 초월 헌금/후원 모듈
// - 카르디아(교회용 키오스크 헌금 결제사) 대응 제안서(2026-09-13, 프로젝트 문서 참고)에 따라
//   기존 분양형 멀티테넌트(communities) + 정산 인프라를 그대로 재사용해 "헌금"이라는 새 도메인을 얹는다.
// - 종교를 코드에 하드코딩하지 않는다: communities.org_type(church/catholic/buddhist/company/association/school/apartment/club/nonprofit/other) +
//   offering_labels(JSON, 항목key->한글명)로 데이터 기반 확장. 신규 종교/교단도 코드 수정 없이 데이터만으로 추가된다.
// - 결제는 기존 토스페이먼츠 연동(getPgConfig('toss'))을 그대로 재사용 - 새 PG 계약 불필요.
// - 실제 개신교 교회 외에 성당·사찰 연결도 예정되어 있어(형님 확인), org_type별 기본 항목명은 일반적인
//   통용 표현으로 채워뒀다 - 실제 연결되는 성당/사찰 담당자에게 정확한 용어(예: 교무금 산정 단위, 시주 익명성 관례)를
//   확인해 offering_labels를 조정하는 절차가 필요하다(제안서 5장에 명시한 한계와 동일).
// ============================================
// 2026-10-22 고객 요청("전체 종교가 아닌 일반회사, 단체 등 모든 것이 입력될 수 있도록")으로 비종교 조직 유형 6종 추가.
// DB CHECK(community_prospects/communities.org_type)와 같은 목록 - docs/migrations/2026-10-22_org_types_widen_community_logo_upload.sql
const ORG_TYPES = ['church', 'catholic', 'buddhist', 'company', 'association', 'school', 'apartment', 'club', 'nonprofit', 'other'];
const RELIGIOUS_ORG_TYPES = ['church', 'catholic', 'buddhist'];
const ORG_TYPE_LABELS = {
  church: '개신교(교회)', catholic: '천주교(성당)', buddhist: '불교(사찰)',
  company: '일반회사', association: '협회·단체', school: '학교·학원', apartment: '아파트·주민모임',
  club: '동호회·모임', nonprofit: '비영리·복지기관', other: '기타'
};
const NON_RELIGIOUS_OFFERING_LABELS = { general: '후원금', special: '특별후원' };
const DEFAULT_OFFERING_LABELS = {
  church: { tithe: '십일조', thanks: '감사헌금', mission: '선교헌금', building: '건축헌금', general: '주정기헌금' },
  catholic: { dues: '교무금', mass: '미사예물', special: '특별헌금', general: '주일헌금' },
  buddhist: { dana: '시주', lantern: '연등접수', incense: '불전', general: '보시금' },
  company: { ...NON_RELIGIOUS_OFFERING_LABELS },
  association: { dues: '회비', general: '후원금', special: '특별후원' },
  school: { general: '후원금', scholarship: '장학후원' },
  apartment: { general: '후원금', special: '공동체 기금' },
  club: { dues: '회비', general: '후원금' },
  nonprofit: { general: '후원금', regular: '정기후원', special: '특별후원' },
  other: { ...NON_RELIGIOUS_OFFERING_LABELS }
};

// 공개: 종교시설 유형/기본 항목명 목록 (관리자가 조직 등록 시 org_type 선택 → 기본 라벨 프리필용)
app.get('/api/offering-org-types', (req, res) => {
  res.json({ success: true, data: { org_types: ORG_TYPES, labels: ORG_TYPE_LABELS, religious: RELIGIOUS_ORG_TYPES, default_labels: DEFAULT_OFFERING_LABELS }, timestamp: new Date().toISOString() });
});

// 헌금/후원 생성 (결제 전 pending 레코드 - 상품주문(POST /api/orders)과 동일한 2단계 결제 패턴)
app.post('/api/offerings', authenticate, async (req, res) => {
  try {
    const { community_slug, items, is_anonymous, memo } = req.body || {};
    if (!community_slug) {
      return res.status(400).json({ error: 'Bad Request', message: 'community_slug가 필요합니다', timestamp: new Date().toISOString() });
    }
    if (!Array.isArray(items) || items.length === 0) {
      return res.status(400).json({ error: 'Bad Request', message: '헌금 항목(items)이 최소 1개 필요합니다', timestamp: new Date().toISOString() });
    }

    const { data: community, error: cErr } = await supabase
      .from('communities').select('id, name, slug, status, offering_labels').eq('slug', community_slug).eq('status', 'active').maybeSingle();
    if (cErr) throw cErr;
    if (!community) return res.status(404).json({ error: 'Not Found', message: '헌금 대상 조직을 찾을 수 없습니다', timestamp: new Date().toISOString() });

    const labels = community.offering_labels || {};
    const verifiedItems = [];
    let totalAmount = 0;
    for (const raw of items) {
      const key = String(raw?.key || '').trim().slice(0, 50);
      const amount = Math.round(Number(raw?.amount));
      if (!key || !Number.isFinite(amount) || amount <= 0) {
        return res.status(400).json({ error: 'Bad Request', message: '헌금 항목은 key와 1원 이상의 amount가 필요합니다', timestamp: new Date().toISOString() });
      }
      // 항목명은 클라이언트가 보낸 값이 아니라 서버가 조직의 offering_labels에서 다시 조회한 값을 신뢰한다(위조 방지)
      verifiedItems.push({ key, label: labels[key] || key, amount });
      totalAmount += amount;
    }
    if (totalAmount <= 0 || totalAmount > 50000000) {
      return res.status(400).json({ error: 'Bad Request', message: '헌금 총액이 올바르지 않습니다(1회 최대 5천만원)', timestamp: new Date().toISOString() });
    }

    const orderNumber = `OFR-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
    const { data, error } = await supabase
      .from('offerings')
      .insert([{
        order_number: orderNumber,
        community_id: community.id,
        user_id: req.user.id,
        items: verifiedItems,
        total_amount: totalAmount,
        status: 'pending',
        is_anonymous: !!is_anonymous,
        memo: memo ? String(memo).slice(0, 500) : null
      }])
      .select()
      .single();
    if (error) throw error;

    res.status(201).json({ success: true, data: { ...data, community_name: community.name }, timestamp: new Date().toISOString() });
  } catch (err) {
    console.error('Error creating offering:', err);
    res.status(500).json({ error: 'Failed to create offering', message: err.message, timestamp: new Date().toISOString() });
  }
});

// 헌금 결제 승인 (토스페이먼츠 - 기존 /api/payments/toss/confirm과 동일한 승인 흐름, 대상 테이블만 offerings)
app.post('/api/offerings/toss/confirm', authenticate, async (req, res) => {
  try {
    const { paymentKey, orderId, amount } = req.body;
    if (!paymentKey || !orderId || !Number.isFinite(Number(amount))) {
      return res.status(400).json({ error: 'Bad Request', message: 'paymentKey, orderId, amount가 모두 필요합니다', timestamp: new Date().toISOString() });
    }

    const { data: offering, error: offErr } = await supabase.from('offerings').select('*').eq('order_number', orderId).eq('user_id', req.user.id).maybeSingle();
    if (offErr) throw offErr;
    if (!offering) return res.status(404).json({ error: 'Not Found', message: '헌금 내역을 찾을 수 없습니다', timestamp: new Date().toISOString() });
    if (offering.status !== 'pending') {
      return res.status(400).json({ error: 'Bad Request', message: `이미 처리된 헌금입니다 (현재 상태: ${offering.status})`, timestamp: new Date().toISOString() });
    }
    if (Math.round(Number(offering.total_amount)) !== Math.round(Number(amount))) {
      return res.status(400).json({ error: 'Bad Request', message: '결제 금액이 헌금 금액과 일치하지 않습니다', timestamp: new Date().toISOString() });
    }

    const config = await getPgConfig('toss');
    if (!config || !config.enabled || !config.secret_key) {
      return res.status(400).json({ error: 'Bad Request', message: '결제 연동이 활성화되어 있지 않습니다', timestamp: new Date().toISOString() });
    }

    const authHeader = 'Basic ' + Buffer.from(config.secret_key + ':').toString('base64');
    const tossResp = await fetch('https://api.tosspayments.com/v1/payments/confirm', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', Authorization: authHeader },
      body: JSON.stringify({ paymentKey, orderId, amount: Number(amount) }),
      signal: AbortSignal.timeout(20000)
    });
    const tossJson = await tossResp.json().catch(() => null);

    if (tossResp.ok) {
      await supabase.from('offering_payments').insert([{ offering_id: offering.id, provider_key: 'toss', payment_key: paymentKey, amount: Number(amount), status: 'approved', raw_response: tossJson }]);
      await supabase.from('offerings').update({ status: 'paid', payment_method: 'toss', paid_at: new Date().toISOString() }).eq('id', offering.id);
      return res.json({ success: true, data: { order_number: offering.order_number, status: 'paid' }, timestamp: new Date().toISOString() });
    } else {
      await supabase.from('offering_payments').insert([{ offering_id: offering.id, provider_key: 'toss', payment_key: paymentKey, amount: Number(amount), status: 'failed', raw_response: tossJson }]);
      return res.status(400).json({ error: 'Payment Failed', message: tossJson?.message || '결제 승인에 실패했습니다', timestamp: new Date().toISOString() });
    }
  } catch (err) {
    console.error('Error confirming offering payment:', err);
    res.status(500).json({ error: 'Failed to confirm payment', message: (process.env.NODE_ENV === 'production' ? '결제 승인에 실패했습니다' : err.message), timestamp: new Date().toISOString() });
  }
});

// 내 헌금 내역 조회 (= 카르디아 offeringhistory 화면이 하려던 일 + 요약 통계)
app.get('/api/offerings/my', authenticate, async (req, res) => {
  try {
    const year = req.query.year ? parseInt(req.query.year, 10) : null;
    let query = supabase.from('offerings').select('*, communities(name, slug, logo_url, org_type)').eq('user_id', req.user.id).eq('status', 'paid').order('paid_at', { ascending: false });
    if (year && Number.isFinite(year)) {
      query = query.gte('paid_at', `${year}-01-01T00:00:00Z`).lt('paid_at', `${year + 1}-01-01T00:00:00Z`);
    }
    const { data, error } = await query;
    if (error) throw error;

    const list = data || [];
    const thisYear = new Date().getFullYear();
    const summary = {
      total_all_time: list.reduce((s, o) => s + Number(o.total_amount || 0), 0),
      total_this_year: list.filter(o => o.paid_at && new Date(o.paid_at).getFullYear() === thisYear).reduce((s, o) => s + Number(o.total_amount || 0), 0),
      count: list.length
    };

    res.json({ success: true, data: list, summary, timestamp: new Date().toISOString() });
  } catch (err) {
    console.error('Error fetching my offerings:', err);
    res.status(500).json({ error: 'Failed to fetch offerings', message: err.message, timestamp: new Date().toISOString() });
  }
});

// 분양 조직(종교시설) 관리자 - 헌금 현황 대시보드 (기존 community-admin 패턴 재사용)
app.get('/api/community-admin/offerings', authenticate, async (req, res) => {
  try {
    const community = await getMyManagedCommunity(req.user.id);
    if (!community) {
      return res.status(404).json({ error: 'Not Found', message: '담당하고 있는 분양 조직이 없습니다', timestamp: new Date().toISOString() });
    }

    const { data: offerings, error } = await supabase
      .from('offerings').select('*').eq('community_id', community.id).eq('status', 'paid').order('paid_at', { ascending: false }).limit(1000);
    if (error) throw error;

    const list = offerings || [];
    const byItem = {};
    list.forEach(o => (o.items || []).forEach(it => {
      byItem[it.key] = byItem[it.key] || { key: it.key, label: it.label, total: 0, count: 0 };
      byItem[it.key].total += Number(it.amount || 0);
      byItem[it.key].count += 1;
    }));
    const thisMonth = new Date().toISOString().slice(0, 7);
    const totalThisMonth = list.filter(o => (o.paid_at || '').slice(0, 7) === thisMonth).reduce((s, o) => s + Number(o.total_amount || 0), 0);

    res.json({
      success: true,
      data: {
        community: { id: community.id, name: community.name, org_type: community.org_type, offering_labels: community.offering_labels },
        recent: list.slice(0, 100).map(o => ({ id: o.id, items: o.items, total_amount: o.total_amount, is_anonymous: o.is_anonymous, paid_at: o.paid_at, user_id: o.is_anonymous ? null : o.user_id })),
        total_all_time: list.reduce((s, o) => s + Number(o.total_amount || 0), 0),
        total_this_month: totalThisMonth,
        count: list.length,
        by_item: Object.values(byItem)
      },
      timestamp: new Date().toISOString()
    });
  } catch (err) {
    console.error('Error fetching community-admin offerings:', err);
    res.status(500).json({ error: 'Failed to fetch offerings', message: err.message, timestamp: new Date().toISOString() });
  }
});

// 분양 조직(종교시설) 관리자 - 자신의 org_type/헌금 항목명 직접 커스터마이즈
app.put('/api/community-admin/offering-labels', authenticate, async (req, res) => {
  try {
    const community = await getMyManagedCommunity(req.user.id);
    if (!community) {
      return res.status(404).json({ error: 'Not Found', message: '담당하고 있는 분양 조직이 없습니다', timestamp: new Date().toISOString() });
    }
    const { org_type, offering_labels } = req.body || {};
    const updates = { updated_at: new Date().toISOString() };
    if (org_type !== undefined) {
      if (!ORG_TYPES.includes(org_type)) {
        return res.status(400).json({ error: 'Bad Request', message: `org_type은 ${ORG_TYPES.join(', ')} 중 하나여야 합니다`, timestamp: new Date().toISOString() });
      }
      updates.org_type = org_type;
    }
    if (offering_labels !== undefined) {
      if (typeof offering_labels !== 'object' || Array.isArray(offering_labels) || !offering_labels) {
        return res.status(400).json({ error: 'Bad Request', message: 'offering_labels는 {key: 한글명} 형태의 객체여야 합니다', timestamp: new Date().toISOString() });
      }
      updates.offering_labels = offering_labels;
    }
    const { data, error } = await supabase.from('communities').update(updates).eq('id', community.id).select('org_type, offering_labels').single();
    if (error) throw error;
    res.json({ success: true, data, message: '헌금 항목 설정이 저장되었습니다', timestamp: new Date().toISOString() });
  } catch (err) {
    console.error('Error updating offering labels:', err);
    res.status(500).json({ error: 'Failed to update offering labels', message: err.message, timestamp: new Date().toISOString() });
  }
});

// ============================================
// 플랫폼 통계 API (홈페이지 실시간 활동 섹션용, 인증 불필요)
// ============================================
// ============================================
// 🔴 홈 "실시간 후기" + "지금 이 순간" — 전부 실제 데이터만 사용(꾸며낸 숫자·이름 없음)
// - 후기: 관리자가 승인한 밴드 후기 + 공개된 구매 후기(작성자는 가운데를 가린 이름)
// - 지금 이 순간: 실제 주문(취소 제외)·후기 작성 이벤트를 시간순으로, 이름은 가려서
// ============================================
const LIVE_ORDER_STATUSES = ['paid', 'processing', 'shipped', 'delivered'];
function firstImage(p) { return p && Array.isArray(p.images_urls) && p.images_urls[0] ? p.images_urls[0] : null; }
function shortText(s, n) { const t = Array.from(String(s || '').replace(/#[^\s#]+/g, ' ').replace(/\s+/g, ' ').trim()); return t.length > n ? t.slice(0, n).join('') + '…' : t.join(''); }

app.get('/api/home/live', async (req, res) => {
  try {
    // "지금 이 순간" 피드는 최근 7일 이벤트만(조용한 기간엔 최근 60일까지 넓혀서 빈 칸을 피한다)
    const FEED_LIMIT = 20;
    const since7 = new Date(Date.now() - 7 * 864e5).toISOString();
    const since60 = new Date(Date.now() - 60 * 864e5).toISOString();
    const [bandRes, revRes, ordRes, cartRes, bandCnt, revCnt, ordCnt] = await Promise.all([
      supabase.from('band_posts_with').select('post_no, author_masked, body, stored_photo_urls, posted_at, products_with(id, name, images_urls)')
        .eq('status', 'approved').eq('kind', 'review').order('posted_at', { ascending: false, nullsFirst: false }).limit(20),
      supabase.from('product_reviews').select('id, rating, comment, created_at, user_id, products_with(id, name, images_urls)')
        .eq('status', 'published').order('created_at', { ascending: false }).limit(20),
      supabase.from('orders_with').select('created_at, payment_at, user_id, items').in('status', LIVE_ORDER_STATUSES)
        .gte('created_at', since60).order('created_at', { ascending: false }).limit(20),
      supabase.from(ACTIVITY_EVENTS_TABLE).select('created_at, user_id, product_id').eq('event_type', 'cart_add')
        .gte('created_at', since60).order('created_at', { ascending: false }).limit(20),
      supabase.from('band_posts_with').select('*', { count: 'exact', head: true }).eq('status', 'approved').eq('kind', 'review'),
      supabase.from('product_reviews').select('*', { count: 'exact', head: true }).eq('status', 'published'),
      supabase.from('orders_with').select('*', { count: 'exact', head: true }).in('status', LIVE_ORDER_STATUSES)
    ]);
    const band = (bandRes.data || []).map(b => ({
      source: 'band', author: b.author_masked || '밴드 회원', text: shortText(b.body, 70), rating: null,
      photo: (b.stored_photo_urls || [])[0] || firstImage(b.products_with),
      product: b.products_with ? { id: b.products_with.id, name: b.products_with.name, image: firstImage(b.products_with) } : null, at: b.posted_at
    }));
    const named = await attachReviewerNames(revRes.data || []);
    const withRev = named.map(r => ({
      source: 'with', author: r.author_name || '구매자', text: shortText(r.comment, 70), rating: r.rating,
      photo: firstImage(r.products_with),
      product: r.products_with ? { id: r.products_with.id, name: r.products_with.name, image: firstImage(r.products_with) } : null, at: r.created_at
    }));
    const allReviews = [...band, ...withRev].filter(r => r.at).sort((a, b) => new Date(b.at) - new Date(a.at));
    const reviews = allReviews.filter(r => r.text || r.photo).slice(0, 12);

    // 주문·장바구니 이벤트의 상품 정보(이름·사진) — 테스트·판매중지 상품은 빼고 지금 판매 중인 상품만
    const firstPid = o => (Array.isArray(o.items) && o.items[0] && o.items[0].product_id) || null;
    const pids = [...new Set([...(ordRes.data || []).map(firstPid), ...(cartRes.data || []).map(c => c.product_id)].filter(Boolean))];
    const { data: prodRows } = pids.length ? await supabase.from('products_with').select('id, name, images_urls').in('id', pids).eq('status', 'active') : { data: [] };
    const prodById = {};
    (prodRows || []).forEach(p => { prodById[p.id] = p; });
    const orders = await attachReviewerNames((ordRes.data || []).filter(o => prodById[firstPid(o)]));
    const carts = await attachReviewerNames((cartRes.data || []).filter(c => prodById[c.product_id]));
    const prodOut = id => (prodById[id] ? { product_id: id, product_name: prodById[id].name, product_image: firstImage(prodById[id]) } : { product_id: null, product_name: null, product_image: null });

    let feed = [
      ...carts.map(c => ({ type: 'cart_add', author: c.author_name || '고객', ...prodOut(c.product_id), extra: 0, at: c.created_at })),
      ...orders.map(o => {
        const items = Array.isArray(o.items) ? o.items : [];
        const first = items[0] || {};
        return { type: 'order', author: o.author_name || '고객', ...prodOut(first.product_id), product_name: (prodById[first.product_id] || {}).name || first.name || '상품', extra: items.length > 1 ? items.length - 1 : 0, at: o.payment_at || o.created_at };
      }),
      ...allReviews.slice(0, 20).map(r => ({ type: r.source === 'band' ? 'band_review' : 'review', author: r.author, product_id: r.product ? r.product.id : null, product_name: r.product ? r.product.name : null, product_image: r.product ? (r.product.image || r.photo) : r.photo, extra: 0, at: r.at }))
    ].filter(e => e.at && new Date(e.at) >= new Date(since60)).sort((a, b) => new Date(b.at) - new Date(a.at));
    const recent = feed.filter(e => new Date(e.at) >= new Date(since7));
    feed = (recent.length >= 4 ? recent : feed).slice(0, FEED_LIMIT);
    // 같은 순간 키(정렬·애니메이션용) — 개인을 식별할 수 있는 값은 담지 않는다
    feed = feed.map(e => ({ ...e, key: [e.type, e.at, e.product_id || ''].join('|') }));

    res.set('Cache-Control', 'public, max-age=20');
    res.json({
      success: true,
      data: { reviews, feed, stats: { bandReviews: bandCnt.count || 0, reviews: revCnt.count || 0, orders: ordCnt.count || 0 } },
      timestamp: new Date().toISOString()
    });
  } catch (err) {
    console.error('Error loading home live:', err);
    res.status(500).json({ error: 'Failed to load live', message: '실시간 정보를 불러오지 못했습니다', timestamp: new Date().toISOString() });
  }
});

// 전체 후기 모아보기 (/reviews 페이지) — source: all | band | with, photo=1이면 사진 있는 후기만
app.get('/api/reviews/all', async (req, res) => {
  try {
    const source = ['band', 'with'].includes(req.query.source) ? req.query.source : 'all';
    const photoOnly = req.query.photo === '1';
    const page = Math.max(1, parseInt(req.query.page, 10) || 1);
    const size = Math.min(48, Math.max(6, parseInt(req.query.size, 10) || 24));
    const rq = String(req.query.q || '').trim().slice(0, 40).toLowerCase();
    const need = rq ? 400 : page * size; // 검색어가 있으면 넉넉히 가져와 글·상품명에서 찾는다
    let band = [], withRev = [], total = 0;
    if (source !== 'with') {
      let q = supabase.from('band_posts_with').select('post_no, author_masked, body, stored_photo_urls, posted_at, posted_label, products_with(id, name, images_urls)', { count: 'exact' })
        .eq('status', 'approved').eq('kind', 'review').order('posted_at', { ascending: false, nullsFirst: false }).range(0, need - 1);
      if (photoOnly) q = q.neq('stored_photo_urls', '{}');
      const { data, error, count } = await q;
      if (error) throw error;
      total += count || 0;
      band = (data || []).map(b => ({ source: 'band', id: 'b' + b.post_no, author: b.author_masked || '밴드 회원', text: String(b.body || '').trim(), rating: null,
        photos: b.stored_photo_urls || [], product: b.products_with ? { id: b.products_with.id, name: b.products_with.name, image: firstImage(b.products_with) } : null, at: b.posted_at }));
    }
    if (source !== 'band' && !photoOnly) {
      const { data, error, count } = await supabase.from('product_reviews').select('id, rating, comment, created_at, user_id, products_with(id, name, images_urls)', { count: 'exact' })
        .eq('status', 'published').order('created_at', { ascending: false }).range(0, need - 1);
      if (error) throw error;
      total += count || 0;
      withRev = (await attachReviewerNames(data || [])).map(r => ({ source: 'with', id: 'r' + r.id, author: r.author_name || '구매자', text: String(r.comment || '').trim(), rating: r.rating,
        photos: [], product: r.products_with ? { id: r.products_with.id, name: r.products_with.name, image: firstImage(r.products_with) } : null, at: r.created_at }));
    }
    let merged = [...band, ...withRev].sort((a, b) => new Date(b.at || 0) - new Date(a.at || 0));
    if (rq) {
      // 후기 글 내용·상품명에서 검색 (띄어쓰기 달라도 찾도록 공백 제거 비교 병행)
      const toks = rq.split(/\s+/).filter(Boolean);
      merged = merged.filter(r => {
        const hay = [r.text, r.product && r.product.name].join(' ').toLowerCase();
        const sq = hay.replace(/\s+/g, '');
        return toks.every(t => hay.includes(t) || sq.includes(t));
      });
      total = merged.length;
    }
    res.set('Cache-Control', 'public, max-age=60');
    res.json({ success: true, data: merged.slice((page - 1) * size, page * size), total, page, size, timestamp: new Date().toISOString() });
  } catch (err) {
    console.error('Error loading all reviews:', err);
    res.status(500).json({ error: 'Failed to load reviews', message: '후기를 불러오지 못했습니다', timestamp: new Date().toISOString() });
  }
});

