// ============================================
// 관심 카테고리 신상품 알림 (제안서 5절 "개인화 푸시/알림톡 캠페인 자동화") - 기존 마케팅 자동화 규칙 엔진
// (등급/구매마일스톤 기반 쿠폰 자동발급)과는 별개로, 재입고/가격추적과 같은 "이벤트 발생 시 알림" 패턴을 그대로 재사용한다.
// 신상품이 등록되는 순간, 같은 카테고리의 다른 상품을 찜해본 적 있는 회원들에게 인앱 알림을 보낸다.
// (구매 이력까지 함께 스캔하면 신호는 더 넓어지지만 상품 등록마다 전체 주문을 훑어야 해 비용이 커지므로,
// 우선은 찜 신호만으로 시작한다 - 필요하면 나중에 구매 이력 기반으로 확장 가능하도록 함수를 분리해두었다.)
async function triggerCategoryInterestNotifications(newProductId, newProductName, category) {
  try {
    if (!category) return;
    const { data: categoryProducts } = await supabase
      .from('products_with')
      .select('id')
      .eq('category', category)
      .eq('status', 'active')
      .neq('id', newProductId);
    const categoryProductIds = (categoryProducts || []).map(p => p.id);
    if (categoryProductIds.length === 0) return; // 같은 카테고리에 다른 상품이 없으면 찜할 기회 자체가 없었으므로 대상도 없다

    const { data: wishlisters } = await supabase.from('wishlist_with').select('user_id').in('product_id', categoryProductIds);
    const userIds = [...new Set((wishlisters || []).map(w => w.user_id))];
    if (userIds.length === 0) return;

    const notifRows = userIds.map(uid => ({
      user_id: uid,
      type: 'category_interest',
      title: '관심 카테고리 신상품 입고',
      message: `관심 있으셨던 카테고리에 새 상품 "${newProductName}"이(가) 들어왔어요!`,
      link: `/product/${newProductId}`
    }));
    await supabase.from('notifications_with').insert(notifRows);
  } catch (err) {
    console.error('Error triggering category interest notifications:', err);
  }
}

// 가격 추적(가격 하락) 알림 (제안서 5절 "가격 하락/재입고 알림") - 재입고 알림과 완전히 같은 인프라(알림 인프라 재사용)를 쓰되,
// 별도 "가격 추적 신청" 버튼/테이블 없이 이미 있는 찜(위시리스트) 목록을 그대로 추적 대상으로 재사용한다(제안서가 권장한 방식).
// 상품 가격이 실제로 "내려갈 때"(관리자가 PUT /api/products/:id로 가격을 수정하는 시점)만 트리거되므로,
// 같은 가격으로 다시 저장해도 "내려갔다"는 조건 자체가 성립하지 않아 중복 알림이 생기지 않는다.
// 가격 비교/최저가 이력 (제안서 6절 "가격 비교/최저가 이력") - 가격이 실제로 바뀔 때마다 스냅샷을 남겨서,
// 나중에 "최근 N일 최저가 대비 지금 얼마나 저렴한지"를 정직하게 보여줄 수 있게 한다.
async function recordPriceHistory(productId, price, discountPrice) {
  try {
    await supabase.from('product_price_history_with').insert({ product_id: productId, price, discount_price: discountPrice === undefined ? null : discountPrice });
  } catch (err) {
    console.error('Error recording price history:', err);
  }
}

function effectivePriceOf(p) {
  const price = Number(p && p.price) || 0;
  const dp = p && p.discount_price !== null && p.discount_price !== undefined ? Number(p.discount_price) : null;
  return (dp !== null && Number.isFinite(dp) && dp < price) ? dp : price;
}

// ============================================
// 구매수량별 가격 옵션 (products_with.quantity_price_options)
// 형식: [{ qty: 2, price: 52920(그 수량의 총액), label: '2세트', badge: '구매많음' }]
// 비어있으면(null/[]) 기존과 완전히 동일하게 "1개 가격 x 수량"으로 계산한다.
// 주문 금액 계산은 반드시 아래 computeProductLineTotal()만 거쳐야 한다 (가격 규칙 단일화 - 다른 가격 규칙
// 예: 타임딜 getFlashDealPrice()가 추가되면 이 함수 안에서 단가 결정 단계에 합류시키면 된다).
// ============================================
const QUANTITY_PRICE_OPTIONS_MAX = 10;

// 관리자 입력값 검증/정규화 - { ok, value(정규화된 배열 또는 null), message }
function normalizeQuantityPriceOptions(raw) {
  if (raw === undefined) return { ok: true, value: undefined };
  if (raw === null || raw === '' || (Array.isArray(raw) && raw.length === 0)) return { ok: true, value: null };
  let arr = raw;
  if (typeof arr === 'string') {
    try { arr = JSON.parse(arr); } catch (e) { return { ok: false, message: '수량별 가격 옵션 형식이 올바르지 않습니다' }; }
  }
  if (!Array.isArray(arr)) return { ok: false, message: '수량별 가격 옵션은 배열이어야 합니다' };
  if (arr.length === 0) return { ok: true, value: null };
  if (arr.length > QUANTITY_PRICE_OPTIONS_MAX) return { ok: false, message: `수량별 가격 옵션은 최대 ${QUANTITY_PRICE_OPTIONS_MAX}개까지 등록할 수 있습니다` };
  const seen = new Set();
  const out = [];
  for (const row of arr) {
    const qty = Number(row && row.qty);
    const price = Number(row && row.price);
    if (!Number.isInteger(qty) || qty < 1 || qty > 9999) return { ok: false, message: '수량은 1 이상의 정수여야 합니다' };
    if (seen.has(qty)) return { ok: false, message: `수량 ${qty}개가 중복되었습니다` };
    if (!Number.isFinite(price) || price <= 0) return { ok: false, message: `수량 ${qty}개의 판매가는 0보다 커야 합니다` };
    seen.add(qty);
    out.push({
      qty,
      price: Math.round(price),
      label: row.label ? String(row.label).trim().slice(0, 30) : '',
      badge: row.badge ? String(row.badge).trim().slice(0, 20) : ''
    });
  }
  out.sort((a, b) => a.qty - b.qty);
  return { ok: true, value: out };
}

// 수량 qty가 등록된 묶음 수량과 정확히 일치하면 그 묶음 총액, 아니면 null
function getQuantityTierPrice(product, qty) {
  const opts = product && Array.isArray(product.quantity_price_options) ? product.quantity_price_options : null;
  if (!opts || opts.length === 0) return null;
  const q = Number(qty);
  const tier = opts.find(o => Number(o.qty) === q);
  if (!tier) return null;
  const price = Number(tier.price);
  return Number.isFinite(price) && price > 0 ? price : null;
}

// 주문 라인 금액 계산 (서버 권위) - unitPrice: 이 상품의 1개 기준 단가(할인가/도매가 반영된 값),
// priceAdjustment: 옵션(variant) 1개당 가격조정, allowTier: 도매가 등 별도 단가 체계일 때는 false
function computeProductLineTotal(product, qty, { unitPrice, priceAdjustment = 0, allowTier = true, priceCtx = null } = {}) {
  const q = Number(qty) || 1;
  const base = unitPrice !== undefined ? Number(unitPrice) : effectivePriceOf(product);
  const adj = Number(priceAdjustment) || 0;
  const rawTierTotal = allowTier ? getQuantityTierPrice(product, q) : null;
  // 채널별 자동 가격: 공동체가는 묶음 총액도 같은 비율로 가감(ChannelPricing.tierTotal), 도매는 묶음가 미적용(null)
  const tierTotal = rawTierTotal !== null && priceCtx ? ChannelPricing.tierTotal(rawTierTotal, priceCtx) : rawTierTotal;
  if (tierTotal !== null) {
    const tier = product.quantity_price_options.find(o => Number(o.qty) === q);
    return { lineTotal: tierTotal + adj * q, tier: { qty: q, price: tierTotal, label: tier.label || '' } };
  }
  return { lineTotal: (base + adj) * q, tier: null };
}

// 저장된 주문 항목의 라인 금액 - 수량별 가격이 적용된 항목은 line_total을 우선 사용 (단가 x 수량이 소수점 반올림으로 어긋나지 않게)
function orderItemLineTotal(it) {
  if (it && it.line_total !== undefined && it.line_total !== null && Number.isFinite(Number(it.line_total))) return Number(it.line_total);
  return Number((it && it.price) || 0) * Number((it && it.quantity) || 1);
}

async function triggerPriceDropNotifications(productId, productName, oldEffectivePrice, newEffectivePrice) {
  try {
    const { data: wishlisters, error } = await supabase.from('wishlist_with').select('user_id').eq('product_id', productId);
    if (error || !wishlisters || wishlisters.length === 0) return;
    const notifRows = wishlisters.map(w => ({
      user_id: w.user_id,
      type: 'price_drop',
      title: '찜한 상품 가격 인하',
      message: `찜하신 "${productName}"의 가격이 ${Math.round(oldEffectivePrice).toLocaleString('ko-KR')}원에서 ${Math.round(newEffectivePrice).toLocaleString('ko-KR')}원으로 내렸습니다!`,
      link: `/product/${productId}`
    }));
    await supabase.from('notifications_with').insert(notifRows);
  } catch (err) {
    console.error('Error triggering price drop notifications:', err);
  }
}

// 재입고 알림 신청 + 인앱 알림
// - 실제 이메일/SMS/푸시 발송 인프라가 없으므로, 정직하게 "사이트 안에서 확인하는 알림"으로 구현한다.
//   품절 상품에 신청해두면, 관리자가 재고를 채워 넣는 순간(재고가 0 이하 -> 양수로 바뀌는 순간) 알림이 생성되고,
//   신청은 1회성으로 자동 해제된다(다시 품절되면 재신청 필요 - 재입고를 계속 알림받고 싶다면 매번 다시 신청).
// ============================================

// 재고가 0 이하 -> 양수로 바뀔 때 호출되어, 해당 상품에 재입고 알림을 신청해둔 회원들에게 알림을 생성하고
// 신청을 정리한다(1회성 알림이므로 알림을 보낸 신청 건은 삭제). 실패해도 재고 처리 자체를 막지 않는다(best-effort).
async function triggerRestockNotifications(productId) {
  try {
    const { data: subs, error: subsErr } = await supabase
      .from('restock_subscriptions_with')
      .select('id, user_id')
      .eq('product_id', productId);
    if (subsErr || !subs || subs.length === 0) return;

    const { data: product } = await supabase.from('products_with').select('id, name').eq('id', productId).maybeSingle();
    const productName = product ? product.name : '상품';

    const notifRows = subs.map(s => ({
      user_id: s.user_id,
      type: 'restock',
      title: '재입고 알림',
      message: `신청하신 "${productName}"이(가) 재입고되었습니다!`,
      link: `/product/${productId}`
    }));
    await supabase.from('notifications_with').insert(notifRows);
    await supabase.from('restock_subscriptions_with').delete().eq('product_id', productId);
  } catch (err) {
    console.error('Error triggering restock notifications:', err);
  }
}

// 재입고 알림 신청 (품절 상품에만 신청 가능 - 재고가 있으면 바로 구매하면 되므로)
app.post('/api/products/:id/restock-notify', authenticate, async (req, res) => {
  try {
    const { data: product, error: productErr } = await supabase
      .from('products_with')
      .select('id, name, stock')
      .eq('id', req.params.id)
      .maybeSingle();
    if (productErr) throw productErr;
    if (!product) return res.status(404).json({ error: 'Not Found', message: '상품을 찾을 수 없습니다', timestamp: new Date().toISOString() });
    if (Number(product.stock) > 0) {
      return res.status(400).json({ error: 'Bad Request', message: '현재 재고가 있는 상품입니다. 바로 구매해주세요!', timestamp: new Date().toISOString() });
    }

    const { data, error } = await supabase
      .from('restock_subscriptions_with')
      .upsert({ product_id: req.params.id, user_id: req.user.id }, { onConflict: 'product_id,user_id', ignoreDuplicates: true })
      .select()
      .maybeSingle();
    if (error) throw error;

    res.status(201).json({ success: true, data, message: '재입고되면 알림을 보내드릴게요', timestamp: new Date().toISOString() });
  } catch (err) {
    console.error('Error subscribing restock notification:', err);
    res.status(500).json({ error: 'Failed to subscribe restock notification', message: err.message, timestamp: new Date().toISOString() });
  }
});

// 재입고 알림 신청 취소
app.delete('/api/products/:id/restock-notify', authenticate, async (req, res) => {
  try {
    const { error } = await supabase
      .from('restock_subscriptions_with')
      .delete()
      .eq('user_id', req.user.id)
      .eq('product_id', req.params.id);
    if (error) throw error;
    res.json({ success: true, message: '재입고 알림 신청을 취소했습니다', timestamp: new Date().toISOString() });
  } catch (err) {
    console.error('Error unsubscribing restock notification:', err);
    res.status(500).json({ error: 'Failed to unsubscribe restock notification', message: err.message, timestamp: new Date().toISOString() });
  }
});

// 내가 신청해둔 재입고 알림 목록 (마이페이지에서 확인/취소용)
app.get('/api/me/restock-notifications', authenticate, async (req, res) => {
  try {
    const { data: subs, error } = await supabase
      .from('restock_subscriptions_with')
      .select('id, product_id, created_at')
      .eq('user_id', req.user.id)
      .order('created_at', { ascending: false });
    if (error) throw error;

    const productIds = (subs || []).map(s => s.product_id);
    let products = [];
    if (productIds.length > 0) {
      const { data: productRows } = await supabase.from('products_with').select('id, name, stock, images_urls').in('id', productIds);
      products = productRows || [];
    }
    const byId = {}; products.forEach(p => { byId[p.id] = p; });
    const result = (subs || []).map(s => ({ subscription_id: s.id, subscribed_at: s.created_at, product: byId[s.product_id] || null })).filter(r => r.product);

    res.json({ success: true, data: result, count: result.length, timestamp: new Date().toISOString() });
  } catch (err) {
    console.error('Error fetching restock notifications:', err);
    res.status(500).json({ error: 'Failed to fetch restock notifications', message: err.message, timestamp: new Date().toISOString() });
  }
});

// 내 알림함 (재입고 알림 등 - 앞으로 다른 유형의 알림도 이 테이블/API를 함께 사용할 수 있도록 범용으로 설계)
// ============================================
// 📣 웹 푸시 알림 (전체 발송 / 개별 발송)
// - 브라우저(안드로이드 크롬·PC 크롬/엣지, 홈화면에 설치한 iOS 16.4+ 앱)에 실제 푸시를 보낸다.
// - VAPID 키는 처음 필요할 때 자동 생성해 platform_settings('web_push_vapid')에 보관(환경변수 설정 불필요).
// - 구독 정보는 push_subscriptions_with(platform으로 WITH+/LIVE+ 구분)에 저장, 만료된 구독(404/410)은 자동 삭제.
// - 개별 발송은 앱 알림함(notifications_with)에도 함께 남겨 푸시를 못 받은 기기에서도 확인할 수 있게 한다.
// ============================================
const webpush = require('web-push');
const PUSH_PLATFORM = process.env.PUSH_PLATFORM || 'withplus';
let vapidKeysCache = null;
async function getVapidKeys() {
  if (vapidKeysCache) return vapidKeysCache;
  const { data } = await supabase.from('platform_settings').select('value').eq('key', 'web_push_vapid').maybeSingle();
  let keys = data && data.value && data.value.publicKey ? data.value : null;
  if (!keys) {
    const generated = webpush.generateVAPIDKeys();
    keys = { publicKey: generated.publicKey, privateKey: generated.privateKey, subject: 'mailto:' + (process.env.PUSH_CONTACT_EMAIL || 'admin@example.com') };
    // 동시에 두 서버가 만들 수 있으므로, 먼저 저장된 값이 있으면 그 값을 쓴다
    await supabase.from('platform_settings').upsert({ key: 'web_push_vapid', value: keys }, { onConflict: 'key', ignoreDuplicates: true });
    const { data: again } = await supabase.from('platform_settings').select('value').eq('key', 'web_push_vapid').maybeSingle();
    if (again && again.value && again.value.publicKey) keys = again.value;
  }
  webpush.setVapidDetails(keys.subject || 'mailto:admin@example.com', keys.publicKey, keys.privateKey);
  vapidKeysCache = keys;
  return keys;
}

app.get('/api/push/public-key', async (req, res) => {
  try {
    const keys = await getVapidKeys();
    res.json({ success: true, publicKey: keys.publicKey, timestamp: new Date().toISOString() });
  } catch (err) {
    console.error('Error loading VAPID key:', err);
    res.status(500).json({ error: 'Failed to load push key', message: '푸시 설정을 불러오지 못했습니다', timestamp: new Date().toISOString() });
  }
});

// 구독 등록 — 로그인 상태면 회원과 연결(개별 발송 대상), 비로그인도 전체 발송은 받을 수 있다
app.post('/api/push/subscribe', optionalAuth, async (req, res) => {
  try {
    const sub = req.body && req.body.subscription;
    if (!sub || typeof sub.endpoint !== 'string' || !/^https:\/\//.test(sub.endpoint) || !sub.keys || !sub.keys.p256dh || !sub.keys.auth) {
      return res.status(400).json({ error: 'Bad Request', message: '구독 정보가 올바르지 않습니다', timestamp: new Date().toISOString() });
    }
    const row = {
      endpoint: sub.endpoint.slice(0, 1000),
      p256dh: String(sub.keys.p256dh).slice(0, 200),
      auth: String(sub.keys.auth).slice(0, 100),
      platform: PUSH_PLATFORM,
      user_agent: String(req.headers['user-agent'] || '').slice(0, 300),
      last_seen_at: new Date().toISOString()
    };
    if (req.user && req.user.id) row.user_id = req.user.id;
    const { error } = await supabase.from('push_subscriptions_with').upsert(row, { onConflict: 'endpoint' });
    if (error) throw error;
    res.json({ success: true, message: '푸시 알림을 받도록 설정했어요', timestamp: new Date().toISOString() });
  } catch (err) {
    console.error('Error saving push subscription:', err);
    res.status(500).json({ error: 'Failed to subscribe', message: '푸시 알림 설정에 실패했습니다', timestamp: new Date().toISOString() });
  }
});

app.post('/api/push/unsubscribe', async (req, res) => {
  try {
    const endpoint = req.body && req.body.endpoint;
    if (typeof endpoint === 'string' && endpoint) await supabase.from('push_subscriptions_with').delete().eq('endpoint', endpoint);
    res.json({ success: true, timestamp: new Date().toISOString() });
  } catch (err) {
    res.status(500).json({ error: 'Failed to unsubscribe', message: '해제에 실패했습니다', timestamp: new Date().toISOString() });
  }
});

// 실제 발송 — 20건씩 병렬, 만료된 구독은 정리
async function sendPushToSubscriptions(subs, payload) {
  await getVapidKeys();
  const body = JSON.stringify(payload);
  let sent = 0, failed = 0;
  const expired = [];
  for (let i = 0; i < subs.length; i += 20) {
    await Promise.all(subs.slice(i, i + 20).map(async s => {
      try {
        await webpush.sendNotification({ endpoint: s.endpoint, keys: { p256dh: s.p256dh, auth: s.auth } }, body, { TTL: 60 * 60 * 24 });
        sent++;
      } catch (e) {
        failed++;
        if (e && (e.statusCode === 404 || e.statusCode === 410)) expired.push(s.endpoint);
      }
    }));
  }
  if (expired.length) {
    for (let i = 0; i < expired.length; i += 100) {
      await supabase.from('push_subscriptions_with').delete().in('endpoint', expired.slice(i, i + 100));
    }
  }
  return { sent, failed, expired: expired.length };
}

// 관리자: 구독 현황
app.get('/api/admin/push/stats', authenticate, requireRole(['admin', 'super_admin']), async (req, res) => {
  try {
    const { count: total } = await supabase.from('push_subscriptions_with').select('id', { count: 'exact', head: true }).eq('platform', PUSH_PLATFORM);
    const { count: members } = await supabase.from('push_subscriptions_with').select('id', { count: 'exact', head: true }).eq('platform', PUSH_PLATFORM).not('user_id', 'is', null);
    res.json({ success: true, data: { total: total || 0, members: members || 0 }, timestamp: new Date().toISOString() });
  } catch (err) {
    res.status(500).json({ error: 'Failed to load push stats', message: err.message, timestamp: new Date().toISOString() });
  }
});

// 관리자: 전체 발송(target='all') / 개별 발송(target='user', email)
app.post('/api/admin/push/send', authenticate, requireRole(['admin', 'super_admin']), async (req, res) => {
  try {
    const { target, email, title, message, link } = req.body || {};
    const t = String(title || '').trim().slice(0, 80);
    const m = String(message || '').trim().slice(0, 300);
    const url = (typeof link === 'string' && /^\/[^/]/.test(link.trim())) ? link.trim().slice(0, 300) : '/';
    if (!t || !m) return res.status(400).json({ error: 'Bad Request', message: '제목과 내용을 입력해주세요', timestamp: new Date().toISOString() });

    let subs = [];
    let userId = null;
    if (target === 'user') {
      const e = String(email || '').trim().toLowerCase();
      if (!e) return res.status(400).json({ error: 'Bad Request', message: '받는 회원의 이메일을 입력해주세요', timestamp: new Date().toISOString() });
      const { data: profile } = await supabase.from('profiles').select('id, email').ilike('email', e).maybeSingle();
      if (!profile) return res.status(404).json({ error: 'Not Found', message: '해당 이메일의 회원이 없습니다', timestamp: new Date().toISOString() });
      userId = profile.id;
      const { data } = await supabase.from('push_subscriptions_with').select('endpoint, p256dh, auth').eq('platform', PUSH_PLATFORM).eq('user_id', userId);
      subs = data || [];
      // 앱 알림함에도 남긴다(푸시를 허용하지 않은 회원도 마이페이지에서 확인)
      await supabase.from('notifications_with').insert([{ user_id: userId, type: 'admin_push', title: t, message: m, link: url, is_read: false }]);
    } else if (target === 'all') {
      for (let from = 0; ; from += 1000) {
        const { data, error } = await supabase.from('push_subscriptions_with').select('endpoint, p256dh, auth').eq('platform', PUSH_PLATFORM).range(from, from + 999);
        if (error) throw error;
        subs.push(...(data || []));
        if (!data || data.length < 1000) break;
      }
    } else {
      return res.status(400).json({ error: 'Bad Request', message: "target은 'all' 또는 'user'여야 합니다", timestamp: new Date().toISOString() });
    }

    const result = await sendPushToSubscriptions(subs, { title: t, body: m, url, tag: 'admin-' + Date.now() });
    res.json({ success: true, data: { target, devices: subs.length, ...result, saved_to_inbox: !!userId }, timestamp: new Date().toISOString() });
  } catch (err) {
    console.error('Error sending push:', err);
    res.status(500).json({ error: 'Failed to send push', message: (process.env.NODE_ENV === 'production' ? '푸시 발송에 실패했습니다' : err.message), timestamp: new Date().toISOString() });
  }
});

// ============================================
// 📈 자동 랭킹 점수 — 실시간 인기 / 구매순 / 오래 본(체류시간) / 노출시간
// 실제 행동 데이터(product_interactions_with)와 주문(orders_with)으로 3분마다 다시 계산한다.
// - popular  : 최근 24시간 조회 + 장바구니(×3) + 구매수량(×8) + 최근 7일 조회(×0.1)
// - sales    : 최근 30일 구매 수량(취소·환불·미결제 제외)
// - dwell    : 최근 7일 상세페이지 평균 체류시간(초)
// - exposure : 최근 7일 목록에서 화면에 실제로 보인 시간 합계(초)
// ============================================
const RANKING_TTL_MS = 3 * 60 * 1000;
let rankingCache = { at: 0, data: null, pending: null };
async function fetchAllRows(build, max) {
  const rows = [];
  for (let from = 0; from < max; from += 1000) {
    const { data, error } = await build().range(from, from + 999);
    if (error) throw error;
    rows.push(...(data || []));
    if (!data || data.length < 1000) break;
  }
  return rows;
}
async function computeRankingScores() {
  const now = Date.now();
  const since24h = now - 24 * 3600 * 1000;
  const since7d = new Date(now - 7 * 24 * 3600 * 1000).toISOString();
  const since30d = new Date(now - 30 * 24 * 3600 * 1000).toISOString();
  const s = {};
  const get = (id) => (s[id] = s[id] || { views24h: 0, views7d: 0, cart24h: 0, sales24h: 0, sales30d: 0, dwellSum: 0, dwellN: 0, exposureMs: 0 });

  const events = await fetchAllRows(() => supabase.from('product_interactions_with')
    .select('product_id, event_type, dwell_ms, created_at')
    .gte('created_at', since7d)
    .in('event_type', ['view', 'view_end', 'cart_add', 'impression'])
    .order('created_at', { ascending: false }), 30000);
  events.forEach(e => {
    if (!e.product_id) return;
    const x = get(e.product_id);
    const t = new Date(e.created_at).getTime();
    if (e.event_type === 'view') { x.views7d++; if (t >= since24h) x.views24h++; }
    else if (e.event_type === 'cart_add') { if (t >= since24h) x.cart24h++; }
    else if (e.event_type === 'view_end') { const d = Number(e.dwell_ms) || 0; if (d > 0 && d < 30 * 60 * 1000) { x.dwellSum += d; x.dwellN++; } }
    else if (e.event_type === 'impression') { const d = Number(e.dwell_ms) || 0; if (d > 0 && d < 10 * 60 * 1000) x.exposureMs += d; }
  });

  const orders = await fetchAllRows(() => supabase.from('orders_with')
    .select('items, status, created_at')
    .gte('created_at', since30d)
    .not('status', 'in', '(cancelled,refunded,pending)')
    .order('created_at', { ascending: false }), 20000);
  orders.forEach(o => {
    const t = new Date(o.created_at).getTime();
    (Array.isArray(o.items) ? o.items : []).forEach(it => {
      if (!it || !it.product_id) return;
      const q = Number(it.quantity) || 1;
      const x = get(it.product_id);
      x.sales30d += q;
      if (t >= since24h) x.sales24h += q;
    });
  });

  const scores = {};
  Object.entries(s).forEach(([id, x]) => {
    scores[id] = {
      popular: Math.round((x.views24h + x.cart24h * 3 + x.sales24h * 8 + x.views7d * 0.1) * 10) / 10,
      sales: x.sales30d,
      dwell: x.dwellN ? Math.round(x.dwellSum / x.dwellN / 100) / 10 : 0,
      exposure: Math.round(x.exposureMs / 100) / 10,
      views24h: x.views24h
    };
  });
  return { updated_at: new Date().toISOString(), scores };
}
async function getRankingScores() {
  if (rankingCache.data && Date.now() - rankingCache.at < RANKING_TTL_MS) return rankingCache.data;
  if (!rankingCache.pending) {
    rankingCache.pending = computeRankingScores()
      .then(d => { rankingCache = { at: Date.now(), data: d, pending: null }; return d; })
      .catch(e => { rankingCache.pending = null; throw e; });
  }
  return rankingCache.pending;
}
app.get('/api/ranking/scores', async (req, res) => {
  try {
    const data = await getRankingScores();
    res.set('Cache-Control', 'public, max-age=60');
    res.json({ success: true, ...data });
  } catch (err) {
    console.error('Error computing ranking scores:', err);
    res.status(500).json({ error: 'Failed to compute ranking', message: '랭킹을 불러오지 못했습니다', timestamp: new Date().toISOString() });
  }
});

// ============================================
// ⚡ 한정수량 초특가 (flash_deals_with) — 관리자가 상품·초특가 가격·한정 수량·기간을 정하면
// 기간 중이고 잔여 수량이 남아 있는 동안에만 서버가 주문 가격을 초특가로 계산한다(getFlashDealPrice).
// - 수량 점유: 주문 생성 시 claim_flash_deal_with RPC로 원자적으로 sold_count를 올린다(한도 초과 불가, 동시 주문 안전).
//   결제 완료 시 점유 기록을 paid로 표시, 취소/환불/24시간 미결제 자동취소/주문 실패 시 release_flash_deal_claims_with로 반환.
// - WITH+와 LIVE+가 같은 DB를 쓰므로 site 컬럼(withplus/liveplus)으로 사이트별로 분리한다.
// ============================================
const FLASH_SITE = UPLOAD_PLATFORM === 'liveplus' ? 'liveplus' : 'withplus';
const FLASH_DEAL_CACHE_MS = 10 * 1000;
let flashDealCache = { at: 0, rows: null, pending: null };

function flashDealStatusOf(d, nowMs) {
  const now = nowMs || Date.now();
  if (!d.is_active) return 'inactive';
  if (now >= new Date(d.ends_at).getTime()) return 'ended';
  if (Number(d.sold_count) >= Number(d.limit_qty)) return 'soldout';
  if (now < new Date(d.starts_at).getTime()) return 'upcoming';
  return 'active';
}
function publicFlashDeal(d, product) {
  const base = product ? Number(product.price) || 0 : 0;
  const dealPrice = Number(d.deal_price) || 0;
  return {
    id: d.id,
    product_id: d.product_id,
    deal_price: dealPrice,
    original_price: base || null,
    discount_rate: base > 0 && dealPrice < base ? Math.round((1 - dealPrice / base) * 100) : 0,
    limit_qty: Number(d.limit_qty),
    sold_count: Number(d.sold_count),
    remaining: Math.max(0, Number(d.limit_qty) - Number(d.sold_count)),
    starts_at: d.starts_at,
    ends_at: d.ends_at,
    sort_order: Number(d.sort_order) || 0,
    status: flashDealStatusOf(d)
  };
}
// 진행중·예정 초특가(사용 중인 것만)를 짧게 캐시해 목록 화면에 붙인다. 주문 가격 계산은 캐시 없이 getFlashDealPrice(fresh)로.
async function loadOpenFlashDeals() {
  const { data, error } = await supabase
    .from('flash_deals_with')
    .select('id, product_id, deal_price, limit_qty, sold_count, starts_at, ends_at, sort_order, is_active')
    .eq('site', FLASH_SITE)
    .eq('is_active', true)
    .gt('ends_at', new Date().toISOString())
    .order('sort_order', { ascending: true })
    .order('ends_at', { ascending: true })
    .limit(500);
  if (error) throw error;
  return data || [];
}
async function getOpenFlashDealsCached() {
  if (flashDealCache.rows && Date.now() - flashDealCache.at < FLASH_DEAL_CACHE_MS) return flashDealCache.rows;
  if (!flashDealCache.pending) {
    flashDealCache.pending = loadOpenFlashDeals()
      .then(rows => { flashDealCache = { at: Date.now(), rows, pending: null }; return rows; })
      .catch(e => { flashDealCache.pending = null; throw e; });
  }
  return flashDealCache.pending;
}
function invalidateFlashDealCache() { flashDealCache = { at: 0, rows: null, pending: null }; }

// 상품별 "지금 적용 가능한" 초특가 1건(진행중 + 잔여 > 0). 같은 상품에 여러 건이 겹치면 가장 싼 것.
// 반환: { [product_id]: dealRow } — 가격 계산(주문/결제)의 단일 진입점.
async function getFlashDealPrice(productIds, opts) {
  const ids = [...new Set((productIds || []).filter(Boolean))];
  if (ids.length === 0) return {};
  let rows;
  if (opts && opts.fresh) {
    const nowIso = new Date().toISOString();
    const { data, error } = await supabase
      .from('flash_deals_with')
      .select('id, product_id, deal_price, limit_qty, sold_count, starts_at, ends_at, sort_order, is_active')
      .eq('site', FLASH_SITE)
      .eq('is_active', true)
      .lte('starts_at', nowIso)
      .gt('ends_at', nowIso)
      .in('product_id', ids);
    if (error) throw error;
    rows = data || [];
  } else {
    const idSet = new Set(ids);
    rows = (await getOpenFlashDealsCached()).filter(d => idSet.has(d.product_id));
  }
  const map = {};
  rows.forEach(d => {
    if (flashDealStatusOf(d) !== 'active') return;
    const cur = map[d.product_id];
    if (!cur || Number(d.deal_price) < Number(cur.deal_price)) map[d.product_id] = d;
  });
  return map;
}
// 상품 목록/상세 응답에 진행중 초특가 정보를 붙인다(화면 표시용 — 실제 결제 가격은 주문 생성 시 서버가 다시 계산).
async function attachFlashDeals(products) {
  const list = Array.isArray(products) ? products : (products ? [products] : []);
  if (list.length === 0) return products;
  try {
    const map = await getFlashDealPrice(list.map(p => p && p.id));
    list.forEach(p => {
      const d = p && map[p.id];
      if (d && Number(d.deal_price) < Number(p.price)) p.flash_deal = publicFlashDeal(d, p);
    });
  } catch (e) { /* 초특가 조회 실패해도 상품 목록 자체는 정상 응답 */ }
  return products;
}
async function releaseFlashDealClaims(orderId) {
  if (!orderId) return 0;
  try {
    const { data, error } = await supabase.rpc('release_flash_deal_claims_with', { p_order_id: orderId });
    if (error) throw error;
    if (data) invalidateFlashDealCache();
    return Number(data) || 0;
  } catch (e) {
    console.error('초특가 수량 반환 실패:', orderId, e.message);
    return 0;
  }
}
async function markFlashDealClaimsPaid(orderId) {
  if (!orderId) return;
  try {
    await supabase.from('flash_deal_claims_with').update({ status: 'paid', paid_at: new Date().toISOString() }).eq('order_id', orderId).eq('status', 'held');
  } catch (e) { console.error('초특가 결제완료 표시 실패:', orderId, e.message); }
}

const FLASH_PRODUCT_COLUMNS = 'id, name, price, discount_price, images_urls, stock, category, rating, review_count, status, brand';
// 공개: 진행중(+예정) 초특가 목록 — 홈 섹션·/deals 페이지에서 사용
app.get('/api/flash-deals', async (req, res) => {
  try {
    const includeUpcoming = req.query.include_upcoming === '1' || req.query.include_upcoming === 'true';
    const limit = Math.min(Math.max(parseInt(req.query.limit, 10) || 60, 1), 200);
    const rows = await getOpenFlashDealsCached();
    const now = Date.now();
    const wanted = rows.filter(d => {
      const st = flashDealStatusOf(d, now);
      return st === 'active' || st === 'soldout' || (includeUpcoming && st === 'upcoming');
    });
    const productIds = [...new Set(wanted.map(d => d.product_id))];
    const productMap = {};
    if (productIds.length) {
      const { data: prods, error } = await supabase.from('products_with').select(FLASH_PRODUCT_COLUMNS).in('id', productIds).eq('status', 'active');
      if (error) throw error;
      (prods || []).forEach(p => { productMap[p.id] = p; });
    }
    const order = { active: 0, soldout: 1, upcoming: 2 };
    const items = wanted
      .filter(d => productMap[d.product_id])
      .map(d => ({ ...publicFlashDeal(d, productMap[d.product_id]), product: productMap[d.product_id] }))
      .sort((a, b) => (order[a.status] - order[b.status]) || (a.sort_order - b.sort_order) || (new Date(a.ends_at) - new Date(b.ends_at)))
      .slice(0, limit);
    const activeEnds = items.filter(i => i.status === 'active').map(i => new Date(i.ends_at).getTime());
    res.set('Cache-Control', 'no-cache');
    res.json({
      success: true,
      data: items,
      soonest_end: activeEnds.length ? new Date(Math.min(...activeEnds)).toISOString() : null,
      server_time: new Date().toISOString(),
      timestamp: new Date().toISOString()
    });
  } catch (err) {
    console.error('Error loading flash deals:', err);
    res.status(500).json({ error: 'Failed to load flash deals', message: '초특가 목록을 불러오지 못했습니다', timestamp: new Date().toISOString() });
  }
});

// 관리자: 초특가 목록(판매/잔여/상태 + 결제완료·결제대기 점유 수량)
app.get('/api/admin/flash-deals', authenticate, requireRole(['admin', 'super_admin']), async (req, res) => {
  try {
    const { data: deals, error } = await supabase
      .from('flash_deals_with')
      .select('*')
      .eq('site', FLASH_SITE)
      .order('sort_order', { ascending: true })
      .order('starts_at', { ascending: false })
      .limit(500);
    if (error) throw error;
    const productIds = [...new Set((deals || []).map(d => d.product_id))];
    const productMap = {};
    if (productIds.length) {
      const { data: prods } = await supabase.from('products_with').select(FLASH_PRODUCT_COLUMNS).in('id', productIds);
      (prods || []).forEach(p => { productMap[p.id] = p; });
    }
    const dealIds = (deals || []).map(d => d.id);
    const claimSum = {};
    if (dealIds.length) {
      const claims = await fetchAllRows(() => supabase.from('flash_deal_claims_with').select('deal_id, quantity, status').in('deal_id', dealIds).in('status', ['held', 'paid']), 20000);
      claims.forEach(c => {
        const s = (claimSum[c.deal_id] = claimSum[c.deal_id] || { held: 0, paid: 0 });
        s[c.status] += Number(c.quantity) || 0;
      });
    }
    const data = (deals || []).map(d => ({
      ...publicFlashDeal(d, productMap[d.product_id]),
      is_active: d.is_active,
      created_at: d.created_at,
      paid_qty: (claimSum[d.id] || {}).paid || 0,
      pending_qty: (claimSum[d.id] || {}).held || 0,
      product: productMap[d.product_id] || null
    }));
    res.json({ success: true, data, server_time: new Date().toISOString(), timestamp: new Date().toISOString() });
  } catch (err) {
    console.error('Error loading admin flash deals:', err);
    res.status(500).json({ error: 'Failed to load flash deals', message: '초특가 목록을 불러오지 못했습니다', timestamp: new Date().toISOString() });
  }
});

async function validateFlashDealInput(body, existing) {
  const b = body || {};
  const out = {};
  const productId = b.product_id !== undefined ? b.product_id : (existing && existing.product_id);
  if (!productId || !/^[0-9a-f-]{36}$/i.test(String(productId))) return { error: '상품을 선택해주세요' };
  const { data: product } = await supabase.from('products_with').select('id, name, price, status').eq('id', productId).maybeSingle();
  if (!product) return { error: '상품을 찾을 수 없습니다' };
  if (b.product_id !== undefined) out.product_id = productId;

  const dealPrice = b.deal_price !== undefined ? Number(b.deal_price) : Number(existing && existing.deal_price);
  if (!Number.isFinite(dealPrice) || dealPrice < 0 || Math.round(dealPrice) !== dealPrice) return { error: '초특가 가격은 0 이상의 정수(원)로 입력해주세요' };
  if (dealPrice >= Number(product.price)) return { error: `초특가 가격은 판매가(${Number(product.price).toLocaleString('ko-KR')}원)보다 낮아야 합니다` };
  if (b.deal_price !== undefined) out.deal_price = dealPrice;

  const limitQty = b.limit_qty !== undefined ? Number(b.limit_qty) : Number(existing && existing.limit_qty);
  if (!Number.isInteger(limitQty) || limitQty < 1 || limitQty > 1000000) return { error: '한정 수량은 1 이상의 정수로 입력해주세요' };
  if (existing && limitQty < Number(existing.sold_count)) return { error: `이미 ${existing.sold_count}개가 판매(점유)되어 그보다 적게 줄일 수 없습니다` };
  if (b.limit_qty !== undefined) out.limit_qty = limitQty;

  const startsAt = b.starts_at !== undefined ? new Date(b.starts_at) : new Date(existing && existing.starts_at);
  const endsAt = b.ends_at !== undefined ? new Date(b.ends_at) : new Date(existing && existing.ends_at);
  if (isNaN(startsAt.getTime()) || isNaN(endsAt.getTime())) return { error: '시작/종료 일시를 입력해주세요' };
  if (endsAt <= startsAt) return { error: '종료 일시는 시작 일시보다 뒤여야 합니다' };
  if (b.starts_at !== undefined) out.starts_at = startsAt.toISOString();
  if (b.ends_at !== undefined) out.ends_at = endsAt.toISOString();

  if (b.sort_order !== undefined) {
    const so = Number(b.sort_order);
    if (!Number.isInteger(so) || so < -100000 || so > 100000) return { error: '노출 순서는 정수로 입력해주세요' };
    out.sort_order = so;
  }
  if (b.is_active !== undefined) out.is_active = !!b.is_active;
  return { values: out, product };
}

app.post('/api/admin/flash-deals', authenticate, requireRole(['admin', 'super_admin']), async (req, res) => {
  try {
    const body = req.body || {};
    for (const k of ['product_id', 'deal_price', 'limit_qty', 'starts_at', 'ends_at']) {
      if (body[k] === undefined || body[k] === null || body[k] === '') return res.status(400).json({ error: 'Bad Request', message: '상품·초특가 가격·한정 수량·시작/종료 일시를 모두 입력해주세요', timestamp: new Date().toISOString() });
    }
    const v = await validateFlashDealInput(body, null);
    if (v.error) return res.status(400).json({ error: 'Bad Request', message: v.error, timestamp: new Date().toISOString() });
    const row = { ...v.values, site: FLASH_SITE, created_by: req.user.id, is_active: body.is_active === undefined ? true : !!body.is_active };
    const { data, error } = await supabase.from('flash_deals_with').insert([row]).select().single();
    if (error) throw error;
    invalidateFlashDealCache();
    res.status(201).json({ success: true, data: publicFlashDeal(data, v.product), timestamp: new Date().toISOString() });
  } catch (err) {
    console.error('Error creating flash deal:', err);
    res.status(500).json({ error: 'Failed to create flash deal', message: '초특가 등록에 실패했습니다', timestamp: new Date().toISOString() });
  }
});

app.put('/api/admin/flash-deals/:id', authenticate, requireRole(['admin', 'super_admin']), async (req, res) => {
  try {
    const { data: existing, error: findErr } = await supabase.from('flash_deals_with').select('*').eq('id', req.params.id).eq('site', FLASH_SITE).maybeSingle();
    if (findErr) throw findErr;
    if (!existing) return res.status(404).json({ error: 'Not Found', message: '초특가를 찾을 수 없습니다', timestamp: new Date().toISOString() });
    const body = { ...(req.body || {}) };
    if (body.product_id !== undefined && body.product_id !== existing.product_id && Number(existing.sold_count) > 0) {
      return res.status(400).json({ error: 'Bad Request', message: '이미 판매된 초특가는 상품을 바꿀 수 없습니다. 새 초특가로 등록해주세요', timestamp: new Date().toISOString() });
    }
    const v = await validateFlashDealInput(body, existing);
    if (v.error) return res.status(400).json({ error: 'Bad Request', message: v.error, timestamp: new Date().toISOString() });
    if (Object.keys(v.values).length === 0) return res.status(400).json({ error: 'Bad Request', message: '변경할 값이 없습니다', timestamp: new Date().toISOString() });
    // limit_qty 축소는 판매(점유) 수량 이상일 때만 — 동시에 주문이 들어와도 DB 제약(sold_count <= limit_qty)이 최종 방어
    const { data, error } = await supabase.from('flash_deals_with').update({ ...v.values, updated_at: new Date().toISOString() }).eq('id', existing.id).select().single();
    if (error) {
      if (String(error.message || '').includes('flash_deals_with_sold_chk')) return res.status(409).json({ error: 'Conflict', message: '그 사이 판매 수량이 늘어 한정 수량을 그만큼 줄일 수 없습니다. 새로고침 후 다시 시도해주세요', timestamp: new Date().toISOString() });
      throw error;
    }
    invalidateFlashDealCache();
    res.json({ success: true, data: publicFlashDeal(data, v.product), timestamp: new Date().toISOString() });
  } catch (err) {
    console.error('Error updating flash deal:', err);
    res.status(500).json({ error: 'Failed to update flash deal', message: '초특가 수정에 실패했습니다', timestamp: new Date().toISOString() });
  }
});

app.delete('/api/admin/flash-deals/:id', authenticate, requireRole(['admin', 'super_admin']), async (req, res) => {
  try {
    const { data: existing } = await supabase.from('flash_deals_with').select('id, sold_count').eq('id', req.params.id).eq('site', FLASH_SITE).maybeSingle();
    if (!existing) return res.status(404).json({ error: 'Not Found', message: '초특가를 찾을 수 없습니다', timestamp: new Date().toISOString() });
    const { count } = await supabase.from('flash_deal_claims_with').select('id', { count: 'exact', head: true }).eq('deal_id', existing.id);
    if (Number(existing.sold_count) > 0 || (count || 0) > 0) {
      return res.status(400).json({ error: 'Bad Request', message: '주문 기록이 있는 초특가는 삭제할 수 없습니다. "사용 안 함"으로 꺼주세요', timestamp: new Date().toISOString() });
    }
    const { error } = await supabase.from('flash_deals_with').delete().eq('id', existing.id);
    if (error) throw error;
    invalidateFlashDealCache();
    res.json({ success: true, timestamp: new Date().toISOString() });
  } catch (err) {
    console.error('Error deleting flash deal:', err);
    res.status(500).json({ error: 'Failed to delete flash deal', message: '초특가 삭제에 실패했습니다', timestamp: new Date().toISOString() });
  }
});

// ============================================
// ⭐ 베스트 상품 자동 순위 — 최근 N일 판매수량·후기 수·평점·장바구니 담기·찜 수를 항목별 최댓값으로 0~1 정규화한 뒤
// 관리자가 정한 가중치로 합산한다. 수동 고정 상품은 지정한 순서대로 맨 위, 제외 상품은 빠진다.
// 설정은 platform_settings(key=best_products_settings[+_live])에 사이트별로 저장(WITH+/LIVE+가 서로 덮어쓰지 않게).
// ============================================
const BEST_SETTINGS_KEY = 'best_products_settings' + LAYOUT_KEY_SUFFIX;
const BEST_DEFAULTS = { period_days: 30, weights: { sales: 40, reviews: 20, rating: 10, cart: 15, wish: 15 }, pinned: [], excluded: [] };
const BEST_TTL_MS = 2 * 60 * 1000;
let bestCache = { at: 0, data: null, pending: null };
const UUID_ONLY_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

function normalizeBestSettings(v) {
  const src = (v && typeof v === 'object') ? v : {};
  const pd = parseInt(src.period_days, 10);
  const w = (src.weights && typeof src.weights === 'object') ? src.weights : {};
  const weights = {};
  Object.keys(BEST_DEFAULTS.weights).forEach(k => {
    const n = Number(w[k]);
    weights[k] = Number.isFinite(n) ? Math.min(Math.max(n, 0), 100) : BEST_DEFAULTS.weights[k];
  });
  const ids = (arr) => [...new Set((Array.isArray(arr) ? arr : []).map(String).filter(id => UUID_ONLY_RE.test(id)))].slice(0, 100);
  const excluded = ids(src.excluded);
  return {
    period_days: Number.isInteger(pd) && pd >= 1 && pd <= 365 ? pd : BEST_DEFAULTS.period_days,
    weights,
    pinned: ids(src.pinned).filter(id => !excluded.includes(id)),
    excluded
  };
}
async function getBestSettings() {
  const { data } = await supabase.from('platform_settings').select('value').eq('key', BEST_SETTINGS_KEY).maybeSingle();
  return normalizeBestSettings(data && data.value);
}
async function computeBestRanking(settings) {
  const s = normalizeBestSettings(settings);
  const sinceIso = new Date(Date.now() - s.period_days * 24 * 3600 * 1000).toISOString();
  const [products, orders, carts, wishes] = await Promise.all([
    fetchAllRows(() => supabase.from('products_with').select(PRODUCT_SAFE_COLUMNS).eq('status', 'active').order('created_at', { ascending: false }), 10000),
    fetchAllRows(() => supabase.from('orders_with').select('items, status, created_at').gte('created_at', sinceIso).not('status', 'in', '(cancelled,refunded,pending)').order('created_at', { ascending: false }), 20000),
    fetchAllRows(() => supabase.from('product_interactions_with').select('product_id').eq('event_type', 'cart_add').gte('created_at', sinceIso).order('created_at', { ascending: false }), 30000),
    fetchAllRows(() => supabase.from('wishlist_with').select('product_id').order('created_at', { ascending: false }), 30000)
  ]);
  const sales = {}, cart = {}, wish = {};
  orders.forEach(o => (Array.isArray(o.items) ? o.items : []).forEach(it => {
    if (it && it.product_id) sales[it.product_id] = (sales[it.product_id] || 0) + (Number(it.quantity) || 1);
  }));
  carts.forEach(c => { if (c.product_id) cart[c.product_id] = (cart[c.product_id] || 0) + 1; });
  wishes.forEach(c => { if (c.product_id) wish[c.product_id] = (wish[c.product_id] || 0) + 1; });

  const excluded = new Set(s.excluded);
  const pool = products.filter(p => !excluded.has(p.id));
  const metric = (p) => ({
    sales: sales[p.id] || 0,
    reviews: Number(p.review_count) || 0,
    // 평점은 후기 수가 적으면 신뢰도가 낮으므로 후기 5건 이상일 때 온전히 반영
    rating: (Number(p.rating) || 0) / 5 * Math.min(1, (Number(p.review_count) || 0) / 5),
    cart: cart[p.id] || 0,
    wish: wish[p.id] || 0
  });
  const rows = pool.map(p => ({ product: p, m: metric(p) }));
  const max = {};
  Object.keys(BEST_DEFAULTS.weights).forEach(k => { max[k] = Math.max(0, ...rows.map(r => r.m[k])); });
  rows.forEach(r => {
    let score = 0;
    Object.keys(s.weights).forEach(k => { if (max[k] > 0) score += s.weights[k] * (r.m[k] / max[k]); });
    r.score = Math.round(score * 100) / 100;
  });
  const pinnedOrder = new Map(s.pinned.map((id, i) => [id, i]));
  rows.sort((a, b) => {
    const pa = pinnedOrder.has(a.product.id), pb = pinnedOrder.has(b.product.id);
    if (pa || pb) return pa && pb ? pinnedOrder.get(a.product.id) - pinnedOrder.get(b.product.id) : (pa ? -1 : 1);
    return (b.score - a.score) || (b.m.reviews - a.m.reviews) || ((Number(b.product.rating) || 0) - (Number(a.product.rating) || 0)) || (new Date(b.product.created_at) - new Date(a.product.created_at));
  });
  return {
    settings: s,
    updated_at: new Date().toISOString(),
    ranking: rows.map((r, i) => ({
      product: r.product,
      rank: i + 1,
      score: r.score,
      pinned: pinnedOrder.has(r.product.id),
      metrics: { sales: r.m.sales, reviews: r.m.reviews, rating: Number(r.product.rating) || 0, cart: r.m.cart, wish: r.m.wish }
    }))
  };
}
async function getBestRankingCached() {
  if (bestCache.data && Date.now() - bestCache.at < BEST_TTL_MS) return bestCache.data;
  if (!bestCache.pending) {
    bestCache.pending = getBestSettings().then(computeBestRanking)
      .then(d => { bestCache = { at: Date.now(), data: d, pending: null }; return d; })
      .catch(e => { bestCache.pending = null; throw e; });
  }
  return bestCache.pending;
}
// 분양 조직이 "선택한 상품만 노출"이면 그 상품만(GET /api/products와 같은 규칙). 해당 없으면 null.
async function getCuratedProductIds(communitySlug) {
  if (!communitySlug) return null;
  const { data: community } = await supabase.from('communities').select('id, product_visibility').eq('slug', communitySlug).eq('status', 'active').maybeSingle();
  if (!community || community.product_visibility !== 'curated') return null;
  const { data: picks } = await supabase.from('community_products').select('product_id').eq('community_id', community.id);
  return new Set((picks || []).map(p => p.product_id));
}

app.get('/api/home/best', async (req, res) => {
  try {
    const limit = Math.min(Math.max(parseInt(req.query.limit, 10) || 24, 1), 100);
    const offset = Math.max(parseInt(req.query.offset, 10) || 0, 0);
    const best = await getBestRankingCached();
    let ranking = best.ranking;
    const curated = await getCuratedProductIds(req.query.community ? String(req.query.community) : '');
    if (curated) ranking = ranking.filter(r => curated.has(r.product.id));
    const page = ranking.slice(offset, offset + limit).map((r, i) => ({ ...r.product, best_rank: offset + i + 1, best_pinned: r.pinned }));
    await attachFlashDeals(page);
    res.set('Cache-Control', 'public, max-age=30');
    res.json({
      success: true,
      data: page,
      total: ranking.length,
      has_more: offset + limit < ranking.length,
      period_days: best.settings.period_days,
      updated_at: best.updated_at,
      timestamp: new Date().toISOString()
    });
  } catch (err) {
    console.error('Error loading best products:', err);
    res.status(500).json({ error: 'Failed to load best products', message: '베스트 상품을 불러오지 못했습니다', timestamp: new Date().toISOString() });
  }
});

